diff --git a/tests/swarm/team-timeout.test.ts b/tests/swarm/team-timeout.test.ts
new file mode 100644
index 0000000..52676de
--- /dev/null
+++ b/tests/swarm/team-timeout.test.ts
@@ -0,0 +1,165 @@
+/**
+ * T5-B2：team 级硬超时单测
+ *
+ * 验证：注入短 timeoutMs 后，若某成员 hang，team.run() 应在超时后
+ * reject（而非永久阻塞）。同时验证超时后 teamAbortCtl 传播使成员 signal 被 abort。
+ */
+
+import { describe, test, expect, beforeEach, afterEach } from "bun:test";
+import { mkdtempSync, rmSync } from "fs";
+import { tmpdir } from "os";
+import { join } from "path";
+import { TeamManager, type TeamOptions, type TeammateSpec } from "../../src/swarm/team.ts";
+
+// --- Mock 基础设施 ---
+
+/** 永不完成的 SubAgent：模拟 hang 成员 */
+class HangingSubAgent {
+  static fromRegistry() {
+    return new HangingSubAgent();
+  }
+  async execute(_task: any, signal?: AbortSignal): Promise<any> {
+    // 等到 signal abort 或 30s（远超测试超时）
+    return new Promise((resolve) => {
+      const timer = setTimeout(() => {
+        resolve({ success: false, output: "不应走到此处" });
+      }, 30_000);
+      timer.unref();
+      if (signal) {
+        signal.addEventListener("abort", () => {
+          clearTimeout(timer);
+          resolve({ success: false, output: "被 team 超时中断" });
+        }, { once: true });
+      }
+    });
+  }
+}
+
+/** 正常完成的 SubAgent */
+class NormalSubAgent {
+  static fromRegistry() {
+    return new NormalSubAgent();
+  }
+  async execute(_task: any, _signal?: AbortSignal): Promise<any> {
+    return { success: true, output: "完成" };
+  }
+}
+
+// mock ProviderRegistry / ToolRegistry
+const mockProviderRegistry = {} as any;
+const mockToolRegistry = {} as any;
+
+let dir: string;
+
+beforeEach(() => {
+  dir = mkdtempSync(join(tmpdir(), "sid-team-timeout-"));
+});
+
+afterEach(() => {
+  if (dir) rmSync(dir, { recursive: true, force: true });
+});
+
+describe("T5-B2 team 级硬超时", () => {
+  test("超时后 run() reject，不永久阻塞", async () => {
+    const members: TeammateSpec[] = [
+      { name: "hang-member", type: "task", task: "会卡住的任务", isolated: false },
+    ];
+    const opts: TeamOptions = {
+      teamName: "test-timeout",
+      members,
+      providerRegistry: mockProviderRegistry,
+      toolRegistry: mockToolRegistry,
+      baseDir: dir,
+      timeoutMs: 200, // 200ms 短超时
+    };
+    const team = new TeamManager(opts);
+
+    // mock SubAgent.fromRegistry → 返回 HangingSubAgent
+    const origImport = (await import("../../src/agent/sub-agent.ts")).SubAgent;
+    const origFromRegistry = origImport.fromRegistry;
+    origImport.fromRegistry = HangingSubAgent.fromRegistry as any;
+
+    try {
+      const start = Date.now();
+      let caught = false;
+      try {
+        await team.run(undefined, Date.now());
+      } catch (err: any) {
+        caught = true;
+        expect(err.message).toMatch(/超时/);
+      }
+      const elapsed = Date.now() - start;
+      expect(caught).toBe(true);
+      // 应在 200ms 左右 reject（允许 300ms 余量）
+      expect(elapsed).toBeLessThan(500);
+    } finally {
+      origImport.fromRegistry = origFromRegistry;
+    }
+  });
+
+  test("超时后 signal 被 abort（成员执行被中断）", async () => {
+    let memberSignalAborted = false;
+
+    class SignalCheckSubAgent {
+      static fromRegistry() { return new SignalCheckSubAgent(); }
+      async execute(_task: any, signal?: AbortSignal): Promise<any> {
+        return new Promise((resolve) => {
+          const timer = setTimeout(() => resolve({ success: false, output: "" }), 30_000);
+          timer.unref();
+          signal?.addEventListener("abort", () => {
+            memberSignalAborted = true;
+            clearTimeout(timer);
+            resolve({ success: false, output: "aborted" });
+          }, { once: true });
+        });
+      }
+    }
+
+    const opts: TeamOptions = {
+      teamName: "test-signal-propagation",
+      members: [{ name: "checker", type: "task", task: "检测", isolated: false }],
+      providerRegistry: mockProviderRegistry,
+      toolRegistry: mockToolRegistry,
+      baseDir: dir,
+      timeoutMs: 150,
+    };
+    const team = new TeamManager(opts);
+
+    const origImport = (await import("../../src/agent/sub-agent.ts")).SubAgent;
+    const origFromRegistry = origImport.fromRegistry;
+    origImport.fromRegistry = SignalCheckSubAgent.fromRegistry as any;
+
+    try {
+      await team.run(undefined, Date.now()).catch(() => {});
+      // 成员的 signal 应被 abort
+      expect(memberSignalAborted).toBe(true);
+    } finally {
+      origImport.fromRegistry = origFromRegistry;
+    }
+  });
+
+  test("正常完成时不触发超时", async () => {
+    const opts: TeamOptions = {
+      teamName: "test-normal",
+      members: [{ name: "fast", type: "task", task: "快速任务", isolated: false }],
+      providerRegistry: mockProviderRegistry,
+      toolRegistry: mockToolRegistry,
+      baseDir: dir,
+      timeoutMs: 5000, // 5s，足够
+    };
+    const team = new TeamManager(opts);
+
+    const origImport = (await import("../../src/agent/sub-agent.ts")).SubAgent;
+    const origFromRegistry = origImport.fromRegistry;
+    origImport.fromRegistry = NormalSubAgent.fromRegistry as any;
+
+    try {
+      const results = await team.run(undefined, Date.now());
+      expect(results).toHaveLength(1);
+      expect(results[0].success).toBe(true);
+      expect(results[0].output).toBe("完成");
+    } finally {
+      origImport.fromRegistry = origFromRegistry;
+    }
+  });
+});
diff --git a/tests/tool/bash-background-reader.test.ts b/tests/tool/bash-background-reader.test.ts
new file mode 100644
index 0000000..8091776
--- /dev/null
+++ b/tests/tool/bash-background-reader.test.ts
@@ -0,0 +1,121 @@
+/**
+ * T5-B4：bash 后台 reader 孤儿清理单测
+ *
+ * 验证：后台进程大量输出时，100ms 超时后 reader.cancel() 被调用，
+ * 不留孤儿 reader 持续消费 stdout。
+ */
+
+import { describe, test, expect } from "bun:test";
+
+describe("T5-B4 bash 后台 reader cancel", () => {
+  test("超时后 reader 被 cancel，不留孤儿", async () => {
+    // 模拟一个持续输出的进程
+    const proc = Bun.spawn(["sh", "-c", "while true; do echo 'output line'; done"], {
+      stdout: "pipe",
+      stderr: "ignore",
+    });
+
+    const reader = proc.stdout.getReader();
+    let readTimedOut = false;
+    let cancelCalled = false;
+
+    const origCancel = reader.cancel.bind(reader);
+    reader.cancel = async (...args: any[]) => {
+      cancelCalled = true;
+      return origCancel(...args);
+    };
+
+    // 复制 T5-B4 的逻辑：100ms 超时后 cancel
+    const readTimer = setTimeout(() => {
+      readTimedOut = true;
+      reader.cancel().catch(() => {});
+    }, 100);
+
+    try {
+      const { value } = await reader.read();
+      if (value && !readTimedOut) {
+        // 正常读到数据，不用管内容（测试重点是 cancel）
+      }
+    } catch {
+      // 忽略读取失败（cancel 后 read 可能抛出）
+    } finally {
+      clearTimeout(readTimer);
+      try { await reader.cancel(); } catch {}
+      try { reader.releaseLock(); } catch {}
+    }
+
+    // cancel 应被调用（无论是超时触发还是 finally 触发）
+    expect(cancelCalled).toBe(true);
+
+    // 清理进程
+    proc.kill();
+    await proc.exited;
+  });
+
+  test("快速完成的进程不需要超时 cancel", async () => {
+    // 只输出一行就退出的进程
+    const proc = Bun.spawn(["echo", "hello"], {
+      stdout: "pipe",
+      stderr: "ignore",
+    });
+
+    const reader = proc.stdout.getReader();
+    let readTimedOut = false;
+
+    const readTimer = setTimeout(() => {
+      readTimedOut = true;
+      reader.cancel().catch(() => {});
+    }, 100);
+
+    let initialOutput = "";
+    try {
+      const { value } = await reader.read();
+      if (value && !readTimedOut) {
+        initialOutput = new TextDecoder().decode(value).slice(0, 500);
+      }
+    } catch {
+      // 忽略
+    } finally {
+      clearTimeout(readTimer);
+      try { await reader.cancel(); } catch {}
+      try { reader.releaseLock(); } catch {}
+    }
+
+    // 快速进程应在超时前完成读取
+    expect(readTimedOut).toBe(false);
+    expect(initialOutput).toContain("hello");
+
+    await proc.exited;
+  });
+
+  test("大量输出进程：超时后 reader 释放锁（releaseLock 不抛）", async () => {
+    // yes 命令持续输出 y\n
+    const proc = Bun.spawn(["yes"], {
+      stdout: "pipe",
+      stderr: "ignore",
+    });
+
+    const reader = proc.stdout.getReader();
+    let lockReleased = false;
+
+    // 150ms 后 cancel + releaseLock
+    await new Promise<void>((resolve) => setTimeout(resolve, 150));
+
+    try { await reader.cancel(); } catch {}
+    try {
+      reader.releaseLock();
+      lockReleased = true;
+    } catch {}
+
+    expect(lockReleased).toBe(true);
+
+    // 验证 releaseLock 后可以再次 getReader（锁已释放）
+    const reader2 = proc.stdout.getReader();
+    expect(reader2).toBeDefined();
+    try { await reader2.cancel(); } catch {}
+    try { reader2.releaseLock(); } catch {}
+
+    proc.kill();
+    await proc.exited;
+  });
+});
diff --git a/tests/tool/lsp-gitignore-timeout.test.ts b/tests/tool/lsp-gitignore-timeout.test.ts
new file mode 100644
index 0000000..87c5b83
--- /dev/null
+++ b/tests/tool/lsp-gitignore-timeout.test.ts
@@ -0,0 +1,141 @@
+/**
+ * T5-B3：lsp git check-ignore 超时 kill 子进程单测
+ *
+ * 验证：当 git check-ignore 子进程 hang 时，超时后应调用 child.kill()，
+ * 不产生孤儿进程。同时验证 signal abort 也能 kill。
+ */
+
+import { describe, test, expect, beforeEach, afterEach } from "bun:test";
+import { mkdtempSync, rmSync, writeFileSync } from "fs";
+import { tmpdir } from "os";
+import { join } from "path";
+import { execSync } from "child_process";
+
+let dir: string;
+
+beforeEach(() => {
+  dir = mkdtempSync(join(tmpdir(), "sid-lsp-gitignore-"));
+  // 初始化一个 git 仓库以便 git check-ignore 能工作
+  execSync("git init", { cwd: dir, stdio: "ignore" });
+});
+
+afterEach(() => {
+  if (dir) rmSync(dir, { recursive: true, force: true });
+});
+
+describe("T5-B3 git check-ignore 超时 kill", () => {
+  test("超时后 child.kill() 被调用——通过脚本模拟 hang 进程", async () => {
+    // 创建一个假的 git 脚本，hang 住不退出
+    const fakeGit = join(dir, "fake-git");
+    writeFileSync(fakeGit, `#!/bin/sh\nsleep 999\n`, { mode: 0o755 });
+
+    const { spawn } = await import("child_process");
+    const child = spawn(fakeGit, [], {
+      cwd: dir,
+      stdio: ["pipe", "pipe", "ignore"],
+    });
+
+    let killed = false;
+    const origKill = child.kill.bind(child);
+    child.kill = (...args: any[]) => {
+      killed = true;
+      return origKill(...args);
+    };
+
+    // 用 "exit" 事件（不等 stdio 流 close，kill 后能立刻触发）
+    const exitPromise = new Promise<void>((resolve) => {
+      child.on("exit", () => resolve());
+      child.on("error", () => resolve());
+    });
+
+    child.stdin!.end();
+
+    let timedOut = false;
+    const timeoutMs = 300; // 用短超时测试（生产中是 5000）
+    const racePromise = new Promise<void>((resolve) =>
+      setTimeout(() => { timedOut = true; resolve(); }, timeoutMs),
+    );
+    await Promise.race([exitPromise, racePromise]);
+
+    if (timedOut && !child.killed) {
+      child.kill();
+    }
+
+    expect(timedOut).toBe(true);
+    expect(killed).toBe(true);
+
+    // kill 后等 exit 事件确认进程已退出
+    await exitPromise;
+  });
+
+  test("signal abort 时立即 kill 子进程", async () => {
+    const fakeGit = join(dir, "fake-git-abort");
+    writeFileSync(fakeGit, `#!/bin/sh\nsleep 999\n`, { mode: 0o755 });
+
+    const { spawn } = await import("child_process");
+    const child = spawn(fakeGit, [], {
+      cwd: dir,
+      stdio: ["pipe", "pipe", "ignore"],
+    });
+
+    let killed = false;
+    const origKill = child.kill.bind(child);
+    child.kill = (...args: any[]) => {
+      killed = true;
+      return origKill(...args);
+    };
+
+    const exitPromise = new Promise<void>((resolve) => {
+      child.on("exit", () => resolve());
+      child.on("error", () => resolve());
+    });
+
+    // 模拟 signal abort path
+    const ctl = new AbortController();
+    const onAbort = () => { if (!child.killed) child.kill(); };
+    ctl.signal.addEventListener("abort", onAbort, { once: true });
+
+    // 100ms 后 abort
+    setTimeout(() => ctl.abort(), 100);
+
+    // 等进程退出（kill 后 exit 事件触发）
+    await exitPromise;
+
+    expect(killed).toBe(true);
+  });
+
+  test("正常退出时不 kill（git check-ignore 正常完成）", async () => {
+    // 用真实 git 仓库 + .gitignore 测试正常场景
+    writeFileSync(join(dir, ".gitignore"), "*.log\n");
+    execSync("git add .gitignore", { cwd: dir, stdio: "ignore" });
+
+    const { spawn } = await import("child_process");
+    const child = spawn("git", ["check-ignore", "--stdin"], {
+      cwd: dir,
+      stdio: ["pipe", "pipe", "ignore"],
+    });
+
+    let stdout = "";
+    child.stdout!.on("data", (c: Buffer) => { stdout += c.toString(); });
+
+    const exitPromise = new Promise<void>((resolve) => {
+      child.on("exit", () => resolve());
+      child.on("error", () => resolve());
+    });
+
+    child.stdin!.write("test.log\ntest.ts\n");
+    child.stdin!.end();
+
+    let timedOut = false;
+    await Promise.race([
+      exitPromise,
+      new Promise<void>((resolve) => setTimeout(() => { timedOut = true; resolve(); }, 5000)),
+    ]);
+
+    expect(timedOut).toBe(false);
+    // test.log 应被 gitignore 匹配
+    expect(stdout.trim()).toContain("test.log");
+    // test.ts 不应被匹配
+    expect(stdout.trim()).not.toContain("test.ts");
+  });
+});

