diff --git a/src/llm/anthropic.ts b/src/llm/anthropic.ts
index e6f264a..751e3c6 100644
--- a/src/llm/anthropic.ts
+++ b/src/llm/anthropic.ts
@@ -855,10 +855,50 @@ function buildToolChoiceParam(params: SendParams): Record<string, unknown> {
