+    // 这是事故的直接断言：模型臆造的名字必须被判为非法
+    expect(known).not.toContain("deepseek");
+    // 而用户真实配置的相似名必须合法（避免修复过度、把真名也拦了）
+    expect(known).toContain("ali-deepseek-v4-pro");
+    expect(known).toContain("ali-deepseek-v4-flash");
+  });
+
+  test("白名单覆盖 availableModels + 主模型 + 降级模型 + subAgentModels", () => {
+    const config = incidentConfig({
+      model: "main-only-model",
+      fallbackModel: "fallback-only-model",
+      availableModels: [{ name: "listed-model", provider: "openai" }],
+    });
+    const registry = new ProviderRegistry(config, { explore: "subagent-only-model" });
+    const known = registry.getKnownModelNames();
+
+    // 后三类即便没写进 availableModels，也是用户有意指定的合法目标，不能判非法
+    expect(known).toContain("listed-model");
+    expect(known).toContain("main-only-model");
+    expect(known).toContain("fallback-only-model");
+    expect(known).toContain("subagent-only-model");
+  });
+
+  test("去重且保序（清单要直接展示给模型，不能有重复噪音）", () => {
+    const config = incidentConfig({
+      model: "dup-model",
+      fallbackModel: "dup-model",
+      availableModels: [{ name: "dup-model", provider: "openai" }, { name: "other", provider: "openai" }],
+    });
+    const registry = new ProviderRegistry(config, { default: "dup-model" });
+    const known = registry.getKnownModelNames();
+
+    expect(known.filter((n) => n === "dup-model")).toHaveLength(1);
+    expect(known[0]).toBe("dup-model"); // availableModels 顺序优先
+  });
+
+  test("fail-open：无任何模型配置时返回空数组（调用方据此放行一切）", () => {
+    const config = incidentConfig({ model: "", fallbackModel: "", availableModels: [] });
+    const registry = new ProviderRegistry(config, {});
+    // 空数组是"无从判断"的信号，绝不能被解读成"没有任何模型合法"
+    expect(registry.getKnownModelNames()).toEqual([]);
+  });
+
+  test("空串 / 纯空白配置不污染白名单", () => {
+    const config = incidentConfig({
+      model: "   ",
+      fallbackModel: "",
+      availableModels: [{ name: "", provider: "openai" }, { name: "real", provider: "openai" }],
+    });
+    const registry = new ProviderRegistry(config, { default: "  " });
+    expect(registry.getKnownModelNames()).toEqual(["real"]);
+  });
+
+  test("模型名两端空白被归一（模型偶发多打空格不应判非法）", () => {
+    const config = incidentConfig({
+      model: "  padded-model  ",
+      availableModels: [],
+      fallbackModel: "",
+    });
+    const registry = new ProviderRegistry(config, {});
+    expect(registry.getKnownModelNames()).toEqual(["padded-model"]);
+  });
+});
+
+describe("SubAgentTool.execute 的 model 拦截（真实修复面）", () => {
+  /** 构造一个只到「参数校验」为止就能返回的 SubAgentTool */
+  function makeTool(config: Config, subAgentModels: Record<string, string> = {}) {
+    const registry = new ProviderRegistry(config, subAgentModels);
+    // toolRegistry 只在真正 spawn 子代理后才被用到；本组测试全部在参数校验阶段返回，
+    // 所以传一个空 Registry 足够，不需要 mock provider/网络。
+    return new SubAgentTool(registry, new Registry() as never);
+  }
+
+  const validCall = {
+    type: "explore",
+    description: "d",
+    prompt: "p",
+  };
+
+  test("事故复现：model=deepseek 被当场拦下，不透传给网关", async () => {
+    const tool = makeTool(incidentConfig(), { default: "ali-deepseek-v4-flash" });
+    const result = await tool.execute({ ...validCall, model: "deepseek" });
+
+    expect(result.isError).toBe(true);
+    expect(result.output).toContain("deepseek");
+    // 报错必须列出可选清单，模型才能自纠（对齐 type 校验的既有范式）
+    expect(result.output).toContain("ali-deepseek-v4-pro");
+    expect(result.output).toContain("ali-deepseek-v4-flash");
+  });
+
+  // ── 「放行」类断言不走 execute() ──
+  //
+  // 放行意味着继续往下真正 spawn 子代理 → 发起真实网络请求。在单测里那既慢又不确定
+  // （实测打出 "Unable to connect" 噪音），且**断言不到点**：网络失败与 model 被拦
+  // 都表现为 isError=true，只能靠 output 文案区分，等于在测文案而非测行为。
+  //
+  // 所以放行侧改为断言「白名单包含该模型」——这正是 execute() 里那个 if 的判据本身，
+  // 拦截侧则走完整 execute()（它在校验阶段就返回，不触网）。两侧合起来覆盖分支全集。
+  test("合法模型名不在拦截集合内", () => {
+    const registry = new ProviderRegistry(incidentConfig(), {});
+    expect(registry.getKnownModelNames()).toContain("ali-deepseek-v4-pro");
+  });
+
+  test("省略 model 不触发校验（params.model 为空即短路）", async () => {
+    // 用一个白名单里必然不存在的值验证「非空才校验」的短路逻辑：
+    // 传空串应被 ?.trim() 短路放行、而非报"不在可用模型列表中"。
+    const tool = makeTool(incidentConfig());
+    const result = await tool.execute({ ...validCall, model: "   ", type: "__nonexistent__" });
+    // 故意给非法 type，让 execute() 在 model 校验**之前**就返回，
+    // 从而确认空白 model 没有抢先触发拦截、也不触网。
+    expect(result.isError).toBe(true);
+    expect(result.output).toContain("无效的子代理类型");
+  });
+
+  test("fail-open：白名单为空时不产生拦截判据", () => {
+    const registry = new ProviderRegistry(
+      incidentConfig({ model: "", fallbackModel: "", availableModels: [] }),
+      {},
+    );
+    // 空清单 → execute() 里 `known.length > 0` 为假 → 无条件放行
+    expect(registry.getKnownModelNames()).toHaveLength(0);
+  });
+
+  test("大小写敏感：错误大小写被拦（网关区分大小写）", async () => {
+    const tool = makeTool(incidentConfig());
+    const result = await tool.execute({ ...validCall, model: "ALI-DeepSeek-V4-Pro" });
+    expect(result.isError).toBe(true);
+    expect(result.output).toContain("不在可用模型列表中");
+  });
+});
+
+describe("sub_agent 的 model 参数 schema 描述", () => {
+  test("描述里明确要求用完整准确名、不要臆造", async () => {
+    // 白名单是"事后拦截"，描述是"事前引导"——两者都要有，否则模型每次都得靠报错学习
+    const src = Bun.file(new URL("../../src/agent/tool.ts", import.meta.url).pathname);
+    const text = await src.text();
+    const modelFieldBlock = text.slice(text.indexOf("model: z"), text.indexOf("cwd: z"));
+    expect(modelFieldBlock).toMatch(/完整模型名|准确名称/);
+    expect(modelFieldBlock).toMatch(/臆造|不要凭印象/);
+  });
+});
diff --git a/tests/llm/strict-wire-contract-reconciliation.test.ts b/tests/llm/strict-wire-contract-reconciliation.test.ts
new file mode 100644
index 0000000..44a0f10
--- /dev/null
+++ b/tests/llm/strict-wire-contract-reconciliation.test.ts
@@ -0,0 +1,241 @@
+/**
+ * 对账测试：wire schema 允许的输入，必须能通过本地 zod 校验（2026-08-01 生产事故）
+ *
+ * ## 事故
+ *
+ * gpt-5.6-luna 会话全程刷屏「参数校验失败」。根因不是模型也不是网关，而是 sid-code
+ * **自己给了模型一份契约，又拒绝按这份契约填写的参数**：
+ *
+ *   1. registry.ts 给内置工具默认打 strict:true
+ *   2. gpt-5.6-luna 声明 protocolKind=openai-responses → 走 Responses API
+ *   3. toStrictJsonSchema() 把 optional 字段塞进 required、类型改成 ["string","null"]
+ *      → 发给模型的契约是「pages 必填，不想给就传 null」
+ *   4. 模型照做传 pages:null
+ *   5. validateToolInput 用**原始** zod schema 校验，`.optional()` 不接受 null → 报错
+ *
+ * 模型无路可走：遵守 wire 契约被拒，不遵守则违反 strict 的 required。
+ * 实测 40 个带 zodSchema 的内置工具里 23 个中招（read/edit/bash/grep/glob/ls 等）。
+ *
+ * ## 为什么要写成"全量对账"而不是逐工具单测
+ *
+ * 这类缺陷的本质是**两个模块各自演进导致的契约漂移**：协议层（openai-responses-request）
+ * 改造 schema 的规则，与工具层（input-validator）校验输入的规则，没有任何机制保证一致。
+ * 只测 read/grep 几个当时中招的工具，挡不住下一个新增 `.optional()` 字段的工具复发。
+ *
+ * 所以这里遍历**全部**带 zodSchema 的内置工具，对每个工具做一次端到端对账：
+ *   按 wire schema 生成一份「合法但极端」的输入（所有 optional 字段填 null）
+ *   → 喂给真实的 validateToolInput
+ *   → 断言不报「received null」，且不被 coerce 静默污染
+ *
+ * 任何人新增工具或改 schema，只要破坏了这个不变量，这个测试就会红。
+ */
+import { describe, test, expect } from "bun:test";
+import { readdirSync } from "node:fs";
+import { join } from "node:path";
+import { z } from "zod/v4";
+import { buildResponsesRequest } from "../../src/llm/openai-responses-request.ts";
+import { validateToolInput } from "../../src/tool/input-validator.ts";
+import type { SendParams, ToolDefinition } from "../../src/llm/types.ts";
+import type { LegacyTool } from "../../src/tool/types.ts";
+
+const TOOL_DIR = join(import.meta.dir, "../../src/tool");
+
+/** 按 JSON Schema 的类型给一个"最小合法值"，用于填必需字段 */
+function sampleForSchema(schema: unknown): unknown {
+  if (!schema || typeof schema !== "object") return "x";
+  const node = schema as Record<string, unknown>;
+  if (Array.isArray(node.enum) && node.enum.length > 0) return node.enum[0];
+  if (node.const !== undefined) return node.const;
+  const rawType = Array.isArray(node.type)
+    ? (node.type as string[]).find((t) => t !== "null")
+    : node.type;
+  switch (rawType) {
+    case "string": return "x";
+    case "number":
+    case "integer": return 1;
+    case "boolean": return true;
+    case "array": return [];
+    case "object": {
+      const props = (node.properties ?? {}) as Record<string, unknown>;
+      const required = Array.isArray(node.required) ? (node.required as string[]) : [];
+      const out: Record<string, unknown> = {};
+      for (const k of required) out[k] = sampleForSchema(props[k]);
+      return out;
+    }
+    default: return "x";
+  }
+}
+
+interface DiscoveredTool {
+  tool: LegacyTool;
+  name: string;
+  jsonSchema: Record<string, unknown>;
+}
+
+/** 实例化 src/tool 下所有导出的、带 zodSchema 的工具类 */
+async function discoverTools(): Promise<DiscoveredTool[]> {
+  const found: DiscoveredTool[] = [];
+  const seen = new Set<string>();
+  const files = readdirSync(TOOL_DIR).filter((f) => f.endsWith(".ts") && !f.includes(".test."));
+
+  for (const file of files) {
+    let mod: Record<string, unknown>;
+    try {
+      mod = (await import(join(TOOL_DIR, file))) as Record<string, unknown>;
+    } catch {
+      continue; // 个别模块有副作用/依赖，跳过不影响对账覆盖面
+    }
+    for (const exported of Object.values(mod)) {
+      if (typeof exported !== "function") continue;
+      let inst: LegacyTool;
+      try {
+        inst = new (exported as new () => LegacyTool)();
+      } catch {
+        continue; // 需要构造参数的工具（如 SubAgentTool）在此路径不实例化
+      }
+      if (typeof inst?.name !== "function" || !inst.zodSchema) continue;
+      const name = inst.name();
+      if (seen.has(name)) continue;
+      let jsonSchema: Record<string, unknown>;
+      try {
+        jsonSchema = z.toJSONSchema(inst.zodSchema as never) as Record<string, unknown>;
+      } catch {
+        continue;
+      }
+      seen.add(name);
+      found.push({ tool: inst, name, jsonSchema });
+    }
+  }
+  return found.sort((a, b) => a.name.localeCompare(b.name));
+}
+
+function wireToolDef(t: DiscoveredTool): ToolDefinition {
+  return { name: t.name, description: "d", input_schema: t.jsonSchema, strict: true } as ToolDefinition;
+}
+
+function buildWire(t: DiscoveredTool) {
+  const params = {
+    model: "gpt-5.6-luna",
+    messages: [{ role: "user", content: [{ type: "text", text: "hi" }] }],
+    maxTokens: 1024,
+    tools: [wireToolDef(t)],
+  } as SendParams;
+  return buildResponsesRequest(params, "gpt-5.6-luna").tools![0];
+}
+
+const TOOLS = await discoverTools();
+
+describe("strict wire 契约与本地校验对账", () => {
+  test("发现到足量内置工具（防止 discover 静默失效导致测试空跑）", () => {
+    expect(TOOLS.length).toBeGreaterThan(30);
+  });
+
+  describe("模型按 wire schema 给 optional 字段传 null → 本地校验必须接受", () => {
+    for (const t of TOOLS) {
+      test(t.name, () => {
+        const wire = buildWire(t);
+        // 降级为非 strict 的工具（record/z.unknown()）不产生"传 null"契约，跳过
+        if (wire.strict !== true) return;
+
+        const wireProps = (wire.parameters.properties ?? {}) as Record<string, unknown>;
+        const originalRequired = new Set(
+          Array.isArray(t.jsonSchema.required) ? (t.jsonSchema.required as string[]) : [],
+        );
+        const optionalKeys = Object.keys(wireProps).filter((k) => !originalRequired.has(k));
+        if (optionalKeys.length === 0) return;
+
+        // 构造一份「完全符合 wire 契约」的极端输入：必需字段给最小合法值，
+        // 所有 optional 字段按契约允许的方式显式传 null。
+        const input: Record<string, unknown> = {};
+        for (const k of originalRequired) {
+          input[k] = sampleForSchema((t.jsonSchema.properties as Record<string, unknown>)?.[k]);
+        }
+        for (const k of optionalKeys) input[k] = null;
+
+        const result = validateToolInput(t.tool, input);
+
+        // 核心断言：绝不能因为 null 报「期望 X，实际收到 null」。
+        // 其他校验失败（如 sampleForSchema 给的占位值不满足业务 refine）不在本测试关注范围，
+        // 只要不是 null 引起的即可。
+        if (!result.ok) {
+          expect(result.message).not.toMatch(/received null|实际收到 null/);
+        }
+      });
+    }
+  });
+
+  describe("coerce 字段的 null 不得被静默污染成 0/空串/false", () => {
+    for (const t of TOOLS) {
+      test(t.name, () => {
+        const wire = buildWire(t);
+        if (wire.strict !== true) return;
+
+        const wireProps = (wire.parameters.properties ?? {}) as Record<string, unknown>;
+        const originalRequired = new Set(
+          Array.isArray(t.jsonSchema.required) ? (t.jsonSchema.required as string[]) : [],
+        );
+        const optionalKeys = Object.keys(wireProps).filter((k) => !originalRequired.has(k));
+        if (optionalKeys.length === 0) return;
+
+        const input: Record<string, unknown> = {};
+        for (const k of originalRequired) {
+          input[k] = sampleForSchema((t.jsonSchema.properties as Record<string, unknown>)?.[k]);
+        }
+        for (const k of optionalKeys) input[k] = null;
+
+        const result = validateToolInput(t.tool, input);
+        if (!result.ok) return;
+
+        // z.coerce.number().optional() 遇 null 会静默返回 0——对 grep.head_limit
+        // （"0 表示无限制"）这类字段是**语义反转**，比报错更危险：无报错、无日志，
+        // 只是行为不对。归一层必须在 coerce 之前把 null 摘掉。
+        const data = result.data as Record<string, unknown>;
+        for (const k of optionalKeys) {
+          expect(data?.[k]).toBeUndefined();
+        }
+      });
+    }
+  });
+
+  describe("strict=true 的工具 schema 不得残留 OpenAI 会 400 的关键字", () => {
+    for (const t of TOOLS) {
+      test(t.name, () => {
+        const wire = buildWire(t);
+        if (wire.strict !== true) return;
+
+        // propertyNames / patternProperties / additionalProperties!=false 描述的是
+        // 动态 key 字典，strict 模式一律 400（2026-08-01 task_create 每轮 400 事故）。
+        // 注意那是**整个请求** 400，该轮所有工具定义都发不出去。
+        const violations: string[] = [];
+        const walk = (node: unknown, path: string) => {
+          if (!node || typeof node !== "object") return;
+          if (Array.isArray(node)) return node.forEach((n, i) => walk(n, `${path}[${i}]`));
+          const obj = node as Record<string, unknown>;
+          if (obj.propertyNames !== undefined) violations.push(`${path}.propertyNames`);
+          if (obj.patternProperties !== undefined) violations.push(`${path}.patternProperties`);
+          if (obj.additionalProperties !== undefined && obj.additionalProperties !== false) {
+            violations.push(`${path}.additionalProperties=${JSON.stringify(obj.additionalProperties)}`);
+          }
+          for (const [k, v] of Object.entries(obj)) walk(v, `${path}.${k}`);
+        };
+        walk(wire.parameters, t.name);
+        expect(violations).toEqual([]);
+      });
+    }
+  });
+
+  test("record 类型工具被正确降级为非 strict（不硬编码工具名，按 schema 特征判定）", () => {
+    // 反向断言：凡原始 schema 里带动态 key 关键字的工具，都必须降级；
+    // 凡不带的，都应保留 strict（否则是降级判定过度激进，白丢 Constrained Decoding）。
+    for (const t of TOOLS) {
+      const raw = JSON.stringify(t.jsonSchema);
+      const hasDynamicKey = raw.includes("propertyNames") || raw.includes("patternProperties");
+      const wire = buildWire(t);
+      if (hasDynamicKey) {
+        expect(wire.strict, `${t.name} 含动态 key 关键字，应降级为非 strict`).toBe(false);
+        // 降级后必须发原始 schema（而非改造过的半成品）
+        expect(wire.parameters).toEqual(t.jsonSchema);
+      }
+    }
+  });
+});
