@@ -0,0 +1,145 @@
+#!/usr/bin/env bun
+/**
+ * 一次性探针 5：零触发归因 + 修正版 truncation / first-prompt（用完即删）
+ */
+
+import { readFileSync, existsSync, readdirSync } from "node:fs";
+import { join } from "node:path";
+import { homedir } from "node:os";
+
+import {
+  isReadonlyProbeCommand, isReadFamilyTool, makeToolProbeCommand, makeSignature,
+} from "../src/query/repeated-readonly-guard.ts";
+import { detectTruncation } from "../src/tool/truncation-detector.ts";
+import { detectInvestigationContext } from "../src/query/hypothesis-guide.ts";
+
+const SESS = join(homedir(), ".sid-code", "trajectories", "sessions");
+
+interface Parsed { id: string; lines: any[]; resultById: Map<string, string> }
+const parsed: Parsed[] = [];
+for (const id of readdirSync(SESS).sort()) {
+  const p = join(SESS, id, "raw.jsonl");
+  if (!existsSync(p)) continue;
+  const lines: any[] = [];
+  for (const line of readFileSync(p, "utf8").split("\n")) {
+    if (!line.trim()) continue;
+    try { const o = JSON.parse(line); if (o.type !== "request_sent") lines.push(o); } catch { }
+  }
+  const resultById = new Map<string, string>();
+  for (const o of lines) for (const m of o.request?.new_messages ?? []) {
+    if (!Array.isArray(m.content)) continue;
+    for (const b of m.content) if (b.type === "tool_result") {
+      const c = typeof b.content === "string" ? b.content
+        : Array.isArray(b.content) ? b.content.map((x: any) => x.text ?? "").join("\n") : "";
+      resultById.set(b.tool_use_id, c);
+    }
+  }
+  parsed.push({ id, lines, resultById });
+}
+
+// ── ① 零触发归因：不考虑 hadOtherActivity 重置，纯看"连续两轮探查签名是否相同" ──
+console.log("=".repeat(80));
+console.log("① repeated-readonly-guard 零触发归因");
+console.log("=".repeat(80));
+let consecSame = 0, consecDiff = 0, resetByActivity = 0, turnsWithProbes = 0;
+let sameCmdDiffOut = 0, sameCmdSameOut = 0;
+for (const { id, lines, resultById } of parsed) {
+  let prevSig: string | null = null;
+  for (const o of lines) {
+    if (!o.response) continue;
+    const probes: Array<{ command: string; output: string }> = [];
+    let other = false;
+    for (const b of o.response.content ?? []) {
+      if (b.type !== "tool_use") continue;
+      const out = resultById.get(b.id) ?? "";
+      if (b.name === "bash") {
+        const cmd = String(b.input?.command ?? "");
+        if (isReadonlyProbeCommand(cmd)) probes.push({ command: cmd, output: out }); else other = true;
+      } else if (isReadFamilyTool(b.name)) probes.push({ command: makeToolProbeCommand(b.name, b.input), output: out });
+      else if (b.name) other = true;
+    }
+    if (!probes.length) { prevSig = null; continue; }
+    turnsWithProbes++;
+    if (other) resetByActivity++;
+    const sig = probes.map((p) => makeSignature(p.command, p.output)).join("\n");
+    const cmdOnly = probes.map((p) => p.command).join("\n");
+    if (prevSig !== null) {
+      if (sig === prevSig) consecSame++; else consecDiff++;
+    }
+    // 同命令不同输出统计（用命令串比对）
+    if ((globalThis as any).__prevCmd === cmdOnly) {
+      if ((globalThis as any).__prevSig === sig) sameCmdSameOut++; else sameCmdDiffOut++;
+    }
+    (globalThis as any).__prevCmd = cmdOnly;
+    (globalThis as any).__prevSig = sig;
+    prevSig = sig;
+  }
+}
+console.log(`产生探查的轮次 ${turnsWithProbes}`);
+console.log(`  其中同轮还有写/产出类工具（hadOtherActivity=true → 强制清零）：${resetByActivity} (${(resetByActivity / turnsWithProbes * 100).toFixed(1)}%)`);
+console.log(`  相邻探查轮签名相同：${consecSame}；不同：${consecDiff}`);
+console.log(`  相邻轮"命令相同"时：输出也相同 ${sameCmdSameOut} 次 / 输出不同 ${sameCmdDiffOut} 次`);
+console.log(`  → 归因：${consecSame === 0 ? "真实轨迹里从未出现『连续两轮完全相同探查+相同输出』，防线判据极窄但未误伤" : "存在连续相同，需查为何未累积到阈值"}`);
+
+// ── ② truncation-detector 修正版（用真实 write/edit 工具入参）──
+console.log("\n" + "=".repeat(80));
+console.log("② truncation-detector 实测（真实 write 工具的 content 入参）");
+console.log("=".repeat(80));
+let considered = 0, hit = 0; const tsamples: string[] = [];
+for (const { id, lines } of parsed) {
+  let turn = 0;
+  for (const o of lines) {
+    if (!o.response) continue; turn++;
+    for (const b of o.response.content ?? []) {
+      if (b.type !== "tool_use") continue;
+      if (b.name !== "write") continue;
+      const content = String(b.input?.content ?? "");
+      const fp = String(b.input?.file_path ?? "");
+      if (content.length < 500) continue;
+      considered++;
+      const r = detectTruncation(content, fp);
+      if (r.isTruncated) {
+        hit++;
+        if (tsamples.length < 10) tsamples.push(`${id} t${turn} ${fp.split("/").pop()} len=${content.length} reason=${r.reason} tail=${JSON.stringify(content.slice(-80))}`);
+      }
+    }
+  }
+}
+console.log(`write 调用中 content ≥500 的样本：${considered}；判定截断 ${hit} (${considered ? (hit / considered * 100).toFixed(1) : 0}%)`);
+tsamples.forEach((s) => console.log("  · " + s));
+
+// ── ③ first prompt 正确提取（跳过 system-reminder / deferred-tools 包裹）──
+console.log("\n" + "=".repeat(80));
+console.log("③ hypothesis-guide detectInvestigationContext（正确提取首个真实用户输入）");
+console.log("=".repeat(80));
+let nPrompt = 0, nHit = 0; const psamples: string[] = [];
+const missSamples: string[] = [];
+for (const { id, lines } of parsed) {
+  // 找首个 request 的 messages 里第一条 user 文本，剔除 system-reminder 包裹
+  let prompt = "";
+  outer: for (const o of lines) {
+    for (const m of (o.request?.messages ?? o.request?.new_messages ?? [])) {
+      if (m.role !== "user") continue;
+      const raw = typeof m.content === "string" ? m.content
+        : (m.content ?? []).filter((b: any) => b.type === "text").map((b: any) => b.text ?? "").join("\n");
+      // 剥离 system-reminder 块与 deferred-tools 块
+      const cleaned = raw
+        .replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, "")
+        .replace(/<available-deferred-tools>[\s\S]*?<\/available-deferred-tools>/g, "")
+        .trim();
+      if (cleaned.length > 5) { prompt = cleaned; break outer; }
+    }
+  }
+  if (!prompt) continue;
+  nPrompt++;
+  if (detectInvestigationContext(prompt)) {
+    nHit++;
+    if (psamples.length < 8) psamples.push(`HIT  ${id} ${JSON.stringify(prompt.slice(0, 100))}`);
+  } else if (missSamples.length < 10) {
+    missSamples.push(`MISS ${id} ${JSON.stringify(prompt.slice(0, 100))}`);
+  }
+}
+console.log(`可提取首轮 prompt 的会话：${nPrompt}；命中调查性上下文 ${nHit} (${nPrompt ? (nHit / nPrompt * 100).toFixed(1) : 0}%)`);
+psamples.forEach((s) => console.log("  · " + s));
+console.log("  未命中样本（核对是否漏判）：");
+missSamples.forEach((s) => console.log("  · " + s));
