@@ -0,0 +1,95 @@
+#!/usr/bin/env bun
+/**
+ * 一次性探针 6：C 类静态约束段（用完即删）
+ * ① 量 system prompt 里约束段的体积（静态成本，每会话每轮都带）
+ * ② 在真实轨迹里找模型「自述被约束绊住」的证据
+ */
+
+import { readFileSync, existsSync, readdirSync } from "node:fs";
+import { join } from "node:path";
+import { homedir } from "node:os";
+
+const SESS = join(homedir(), ".sid-code", "trajectories", "sessions");
+
+// ── ① 约束段体积 ──
+const sp = readFileSync("src/config/system-prompt.ts", "utf8");
+function section(startMark: string, endMark: string): number {
+  const i = sp.indexOf(startMark); if (i < 0) return 0;
+  const j = sp.indexOf(endMark, i); if (j < 0) return 0;
+  return j + endMark.length - i;
+}
+console.log("=".repeat(80));
+console.log("① 静态约束段体积（源码字符数，近似 token = 中文×0.65 / ASCII×0.2）");
+console.log("=".repeat(80));
+const secs: Array<[string, number]> = [
+  ["<constraints> 行为约束", section("<constraints>", "</constraints>")],
+  ["<output-redlines> 七大红线+五扩展", section("<output-redlines>", "</output-redlines>")],
+  ["<answer-discipline> 回答规范", section("<answer-discipline>", "</answer-discipline>")],
+];
+let tot = 0;
+for (const [n, c] of secs) { tot += c; console.log(`  ${n.padEnd(38)} ${String(c).padStart(6)} 字符`); }
+console.log(`  ${"合计".padEnd(38)} ${String(tot).padStart(6)} 字符  ≈ ${Math.round(tot * 0.5)} tokens（中英混排粗估）`);
+
+// 真实 system prompt 体积（从轨迹里取）
+let spChars = 0, spSample = "";
+outer: for (const id of readdirSync(SESS).sort().reverse()) {
+  const p = join(SESS, id, "raw.jsonl");
+  if (!existsSync(p)) continue;
+  for (const line of readFileSync(p, "utf8").split("\n")) {
+    if (!line.trim()) continue;
+    let o: any; try { o = JSON.parse(line); } catch { continue; }
+    const s = o.request?.system;
+    if (!s) continue;
+    const txt = typeof s === "string" ? s : Array.isArray(s) ? s.map((b: any) => b.text ?? "").join("\n") : "";
+    if (txt.length > 100) { spChars = txt.length; spSample = txt; break outer; }
+  }
+}
+console.log(`\n  实际 system prompt 总长：${spChars} 字符`);
+if (spChars) console.log(`  约束段占 system prompt：${(tot / spChars * 100).toFixed(1)}%`);
+for (const [n] of secs) {
+  const mark = n.split(" ")[0];
+  console.log(`  system prompt 含 ${mark}：${spSample.includes(mark.replace(/[<>]/g, "").split(" ")[0]) || spSample.includes(mark)}`);
+}
+
+// ── ② 模型自述被约束绊住 ──
+console.log("\n" + "=".repeat(80));
+console.log("② 轨迹里模型自述被约束绊住的证据");
+console.log("=".repeat(80));
+const CUES = [
+  "红线", "约束要求", "约束不允许", "输出红线", "RL-0", "answer-discipline",
+  "回答规范", "不允许我", "按照约束", "根据约束", "受约束", "违反约束",
+  "必须先 grep", "先 grep 举证", "降级为", "疑似，待核验",
+];
+const found = new Map<string, Array<{ s: string; t: number; ex: string }>>();
+for (const c of CUES) found.set(c, []);
+let turns = 0;
+for (const id of readdirSync(SESS).sort()) {
+  const p = join(SESS, id, "raw.jsonl");
+  if (!existsSync(p)) continue;
+  let turn = 0;
+  for (const line of readFileSync(p, "utf8").split("\n")) {
+    if (!line.trim()) continue;
+    let o: any; try { o = JSON.parse(line); } catch { continue; }
+    if (o.type === "request_sent" || !o.response) continue;
+    turn++; turns++;
+    // 只看模型自己产出的 text + thinking
+    let blob = "";
+    for (const b of o.response.content ?? []) {
+      if (b.type === "text") blob += (b.text ?? "") + "\n";
+      if (b.type === "thinking") blob += (b.thinking ?? "") + "\n";
+    }
+    for (const c of CUES) {
+      const i = blob.indexOf(c);
+      if (i >= 0) found.get(c)!.push({ s: id, t: turn, ex: blob.slice(Math.max(0, i - 60), i + 120).replace(/\n/g, " ⏎ ") });
+    }
+  }
+}
+console.log(`扫描 ${turns} 个 assistant 响应（含 thinking）\n`);
+for (const c of CUES) {
+  const h = found.get(c)!;
+  if (!h.length) continue;
+  console.log(`### "${c}" — ${h.length} 次`);
+  for (const x of h.slice(0, 4)) console.log(`  [${x.s} t${x.t}] ${x.ex.slice(0, 175)}`);
+}
+const totalCue = [...found.values()].reduce((a, b) => a + b.length, 0);
+console.log(`\n合计线索命中 ${totalCue} 次 / ${turns} 轮 (${(totalCue / turns * 100).toFixed(1)}%)`);
diff --git a/scripts/_probe-injected.ts b/scripts/_probe-injected.ts
new file mode 100644
index 0000000..6e60bf8
--- /dev/null
+++ b/scripts/_probe-injected.ts
@@ -0,0 +1,103 @@
+#!/usr/bin/env bun
+/**
+ * 一次性探针 2：统计**真实注入过**的 reminder（用完即删）
+ *
+ * 与探针 1（重放判定函数）互补：这里不模拟，直接在 raw.jsonl 的 request 消息里
+ * 找各 builder 产出文案的特征串——出现即证明该防线在生产里真的注入过。
+ */
+
+import { readFileSync, existsSync, readdirSync } from "node:fs";
+import { join } from "node:path";
+import { homedir } from "node:os";
+
+const SESS = join(homedir(), ".sid-code", "trajectories", "sessions");
+
+/** 各防线注入文案的唯一特征串（取自 builder 源码原文） */
+const FINGERPRINTS: Array<{ key: string; needle: string; file: string }> = [
+  { key: "thinking-divergence", needle: "思考量持续激增", file: "src/query/thinking-divergence.ts:100" },
+  { key: "output-stall", needle: "轮的产出量都很小", file: "src/query/output-stall.ts:106" },
+  { key: "context-pressure", needle: "上下文使用率已达", file: "src/query/context-pressure.ts:85" },
+  { key: "repeated-readonly(remind)", needle: "你已连续多轮执行相同的只读命令", file: "src/query/repeated-readonly-guard.ts:279" },
+  { key: "repeated-readonly(terminate)", needle: "已连续多轮空转于只读命令", file: "src/query/repeated-readonly-guard.ts:315" },
+  { key: "todo-reminder", needle: "这是你当前的任务清单", file: "src/query/todo-reminder.ts:111" },
+  { key: "todo-gate", needle: "检测到你试图结束本轮对话", file: "src/query/todo-reminder.ts:125" },
+  { key: "todo-gate-exhausted", needle: "已达自动续推上限", file: "src/query/todo-reminder.ts:140" },
+  { key: "todo-gate-forgot-mark", needle: "已完成本轮工作并收尾", file: "src/query/todo-reminder.ts:50" },
+  { key: "unanswered-end-turn", needle: "没有产出面向用户的有效答复", file: "src/query/todo-reminder.ts:68" },
+  { key: "work-log(progress)", needle: "【工作日志】", file: "src/query/work-log.ts:137" },
+  { key: "hypothesis-guide", needle: "这看起来是一个核查 / 排查 / 审计类任务", file: "src/query/hypothesis-guide.ts:238" },
+  { key: "soft-turn-limit", needle: "软提醒阈值", file: "src/query/soft-turn-limit.ts:60" },
+  { key: "empty-param", needle: "空参数", file: "src/query/empty-param.ts" },
+  { key: "permission-mode", needle: "当前权限模式", file: "src/query/permission-reminder.ts" },
+  { key: "lsp-diagnostic", needle: "LSP 诊断（来自语言服务器", file: "src/query/loop.ts:625" },
+  { key: "contradiction", needle: "假设待裁决", file: "src/query/hypothesis-ledger.ts" },
+  { key: "goal-reminder", needle: "当前目标", file: "src/goal/budget.ts" },
+  { key: "truncation-notice", needle: "被截断", file: "src/tool/truncation-detector.ts" },
+];
+
+interface Hit { sess: string; turn: number; excerpt: string }
+const hits = new Map<string, Hit[]>();
+for (const f of FINGERPRINTS) hits.set(f.key, []);
+
+let sessCount = 0, turnCount = 0;
+const sessWith = new Map<string, Set<string>>();
+for (const f of FINGERPRINTS) sessWith.set(f.key, new Set());
+
+for (const id of readdirSync(SESS).sort()) {
+  const p = join(SESS, id, "raw.jsonl");
+  if (!existsSync(p)) continue;
+  sessCount++;
+  let turn = 0;
+  for (const line of readFileSync(p, "utf8").split("\n")) {
+    if (!line.trim()) continue;
+    let o: any;
+    try { o = JSON.parse(line); } catch { continue; }
+    if (o.type === "request_sent") continue;
+    if (!o.request) continue;
+    turn++; turnCount++;
+    // 只看本轮新增消息，避免历史重复计数
+    const msgs = o.request.new_messages ?? [];
+    let blob = "";
+    for (const m of msgs) {
+      const c = m.content;
+      if (typeof c === "string") blob += c + "\n";
+      else if (Array.isArray(c)) {
+        for (const b of c) {
+          if (b.type === "text") blob += (b.text ?? "") + "\n";
+          if (b.type === "tool_result" && typeof b.content === "string") blob += b.content + "\n";
+        }
+      }
+    }
+    for (const f of FINGERPRINTS) {
+      if (blob.includes(f.needle)) {
+        const i = blob.indexOf(f.needle);
+        hits.get(f.key)!.push({ sess: id, turn, excerpt: blob.slice(Math.max(0, i - 40), i + 150).replace(/\n/g, " ⏎ ") });
+        sessWith.get(f.key)!.add(id);
+      }
+    }
+  }
+}
+
+console.log("=".repeat(80));
+console.log(`真实注入统计：${sessCount} 个含 raw.jsonl 的会话，${turnCount} 个 assistant 轮次`);
+console.log("=".repeat(80));
+console.log(`\n${"防线".padEnd(30)}${"注入次数".padStart(10)}${"涉及会话".padStart(10)}`);
+console.log("-".repeat(80));
+for (const f of FINGERPRINTS) {
+  const h = hits.get(f.key)!;
+  const s = sessWith.get(f.key)!;
+  const rate = ((h.length / turnCount) * 100).toFixed(1);
+  console.log(`${f.key.padEnd(30)}${String(h.length).padStart(10)}${String(s.size).padStart(10)}   ${rate}%  ${f.file}`);
+}
+
+console.log("\n" + "=".repeat(80));
+console.log("命中样本（每类最多 6 条，供人工核对真假阳性）");
+console.log("=".repeat(80));
+for (const f of FINGERPRINTS) {
+  const h = hits.get(f.key)!;
+  if (h.length === 0) continue;
+  console.log(`\n### ${f.key}  (${h.length} 次)`);
+  for (const x of h.slice(0, 6)) {
+    console.log(`  [${x.sess} t${x.turn}] ${x.excerpt.slice(0, 190)}`);
+  }
+}
