+#!/usr/bin/env bun
+/**
+ * 一次性探针 8：noProgressNagCount 共享计数器互相饿死（用完即删）
+ *
+ * loop.ts:678/687（todo）与 710/717（work-log）读写**同一个** state.noProgressNagCount，
+ * cap=MAX_NO_PROGRESS_NAGS=2。两者是独立提醒、各有独立 lastInjectedXxxText 去重，
+ * 但共享封顶预算 → 一方用掉额度会掐断另一方。此脚本用真实 decideNagInjection 复现。
+ */
+
+import { decideNagInjection, MAX_NO_PROGRESS_NAGS } from "../src/query/reminder-throttle.ts";
+
+const CAP = MAX_NO_PROGRESS_NAGS;
+
+/** 模拟：todo 内容每轮微变（如"仍待办 N 项"的 N 变化）→ 去重失效，持续吃额度 */
+function simulate(sharedCounter: boolean) {
+  let shared = 0;
+  let todoCount = 0, wlCount = 0;
+  let lastTodo: string | undefined, lastWl: string | undefined;
+  const log: string[] = [];
+
+  for (let turn = 8; turn <= 48; turn += 8) {
+    // todo 文案：每次略有不同（模型改了描述但没翻状态位 → 常见）
+    const todoText = `清单：${turn} 轮时仍待办 3 项（描述微调 ${turn}）`;
+    const getCount = () => (sharedCounter ? shared : todoCount);
+    const dT = decideNagInjection({ candidate: todoText, lastInjectedText: lastTodo, noProgressNagCount: getCount() });
+    if (dT.inject) {
+      lastTodo = todoText;
+      if (dT.countedAsNoProgress) { if (sharedCounter) shared++; else todoCount++; }
+      log.push(`t${turn} todo=注入(counter→${sharedCounter ? shared : todoCount})`);
+    } else {
+      log.push(`t${turn} todo=**抑制**`);
+    }
+
+    // work-log 文案：同样每轮微变
+    const wlText = `【工作日志】${turn} 轮：已完成 2 项 / 仍待办 3 项（描述微调 ${turn}）`;
+    const getCount2 = () => (sharedCounter ? shared : wlCount);
+    const dW = decideNagInjection({ candidate: wlText, lastInjectedText: lastWl, noProgressNagCount: getCount2() });
+    if (dW.inject) {
+      lastWl = wlText;
+      if (dW.countedAsNoProgress) { if (sharedCounter) shared++; else wlCount++; }
+      log.push(`t${turn} worklog=注入(counter→${sharedCounter ? shared : wlCount})`);
+    } else {
+      log.push(`t${turn} worklog=**抑制**`);
+    }
+  }
+  return log;
+}
+
+console.log("=".repeat(80));
+console.log(`noProgressNagCount 共享 vs 独立（cap=${CAP}）`);
+console.log("=".repeat(80));
+
+console.log(`\n【现状：共享同一计数器（loop.ts:678/687 与 710/717）】`);
+const a = simulate(true);
+a.forEach((l) => console.log("  " + l));
+const aInj = a.filter((l) => l.includes("注入(")).length;
+const aSup = a.filter((l) => l.includes("抑制")).length;
+console.log(`  → 注入 ${aInj} 次，抑制 ${aSup} 次`);
+
+console.log(`\n【假设修复：两类各自独立计数器】`);
+const b = simulate(false);
+b.forEach((l) => console.log("  " + l));
+const bInj = b.filter((l) => l.includes("注入(")).length;
+const bSup = b.filter((l) => l.includes("抑制")).length;
+console.log(`  → 注入 ${bInj} 次，抑制 ${bSup} 次`);
+
+console.log(`\n差异：共享计数器下少注入 ${bInj - aInj} 次（其中包含被另一类"吃掉额度"而饿死的提醒）`);
+
+// 关键推论验证：第一类连注 2 次即耗尽 cap，第二类从未获得机会
+console.log("\n" + "=".repeat(80));
+console.log("极端场景：todo 先连注 2 次耗尽 cap → work-log 首次就被抑制（从未注入过）");
+console.log("=".repeat(80));
+let shared = 0; let lastT: string | undefined, lastW: string | undefined;
+for (let i = 1; i <= 3; i++) {
+  const t = `todo 版本 ${i}`;
+  const d = decideNagInjection({ candidate: t, lastInjectedText: lastT, noProgressNagCount: shared });
+  if (d.inject) { lastT = t; if (d.countedAsNoProgress) shared++; }
+  console.log(`  第${i}次 todo: ${d.inject ? "注入" : "抑制"}  counter=${shared}`);
+}
+const w = `【工作日志】首次注入尝试`;
+const dw = decideNagInjection({ candidate: w, lastInjectedText: lastW, noProgressNagCount: shared });
+console.log(`  work-log 首次尝试（lastInjectedText=undefined，绝无重复）: ${dw.inject ? "注入" : "**被抑制** ← 被 todo 吃掉额度而饿死"}`);
