+#!/usr/bin/env bun
+/**
+ * 一次性探针 3：注入冗余/重复度分析（用完即删）
+ * 关注：同一轮里是否注入了多条内容重叠的 reminder；连续轮次是否注入近乎相同的文本。
+ */
+
+import { readFileSync, existsSync, readdirSync } from "node:fs";
+import { join } from "node:path";
+import { homedir } from "node:os";
+
+const SESS = join(homedir(), ".sid-code", "trajectories", "sessions");
+
+const MARKERS: Array<[string, string]> = [
+  ["todo", "这是你当前的任务清单"],
+  ["worklog", "【工作日志】"],
+  ["perm", "当前权限模式为"],
+  ["pressure", "上下文使用率已达"],
+  ["hypguide", "这看起来是一个核查"],
+  ["goal", "【当前目标】"],
+];
+
+interface T { sess: string; turn: number; kinds: string[]; reminderChars: number; texts: Map<string, string> }
+const rows: T[] = [];
+
+for (const id of readdirSync(SESS).sort()) {
+  const p = join(SESS, id, "raw.jsonl");
+  if (!existsSync(p)) continue;
+  let turn = 0;
+  for (const line of readFileSync(p, "utf8").split("\n")) {
+    if (!line.trim()) continue;
+    let o: any; try { o = JSON.parse(line); } catch { continue; }
+    if (o.type === "request_sent" || !o.request) continue;
+    turn++;
+    let blob = "";
+    for (const m of o.request.new_messages ?? []) {
+      const c = m.content;
+      if (typeof c === "string") blob += c + "\n";
+      else if (Array.isArray(c)) for (const b of c) if (b.type === "text") blob += (b.text ?? "") + "\n";
+    }
+    const kinds: string[] = []; const texts = new Map<string, string>();
+    let chars = 0;
+    for (const [k, needle] of MARKERS) {
+      const i = blob.indexOf(needle);
+      if (i < 0) continue;
+      kinds.push(k);
+      // 抽出该 reminder 所在的 <system-reminder> 块
+      const start = blob.lastIndexOf("<system-reminder>", i);
+      const end = blob.indexOf("</system-reminder>", i);
+      const block = start >= 0 && end > start ? blob.slice(start, end + 18) : blob.slice(i, i + 400);
+      texts.set(k, block);
+      chars += block.length;
+    }
+    if (kinds.length) rows.push({ sess: id, turn, kinds, reminderChars: chars, texts });
+  }
+}
+
+console.log("=".repeat(80));
+console.log("① 同一轮注入多条 reminder 的情况");
+console.log("=".repeat(80));
+const multi = rows.filter((r) => r.kinds.length > 1);
+console.log(`有注入的轮次：${rows.length}；其中同轮多条：${multi.length}`);
+const combo = new Map<string, number>();
+for (const r of rows) {
+  const k = r.kinds.slice().sort().join("+");
+  combo.set(k, (combo.get(k) ?? 0) + 1);
+}
+for (const [k, v] of [...combo.entries()].sort((a, b) => b[1] - a[1])) console.log(`  ${String(v).padStart(4)}×  ${k}`);
+
+console.log("\n" + "=".repeat(80));
+console.log("② todo + worklog 同轮共现（内容重叠：两者都列同一份清单）");
+console.log("=".repeat(80));
+const both = rows.filter((r) => r.kinds.includes("todo") && r.kinds.includes("worklog"));
+console.log(`共现轮次：${both.length}`);
+for (const r of both.slice(0, 5)) {
+  console.log(`\n[${r.sess} t${r.turn}] 两块合计 ${r.reminderChars} 字符`);
+  console.log(`  todo   : ${(r.texts.get("todo") ?? "").replace(/\n/g, " ⏎ ").slice(0, 240)}`);
+  console.log(`  worklog: ${(r.texts.get("worklog") ?? "").replace(/\n/g, " ⏎ ").slice(0, 240)}`);
+}
+
+console.log("\n" + "=".repeat(80));
+console.log("③ 连续注入的 worklog 文本相似度（是否在刷近乎相同的提醒）");
+console.log("=".repeat(80));
+const bySess = new Map<string, T[]>();
+for (const r of rows) {
+  if (!r.kinds.includes("worklog")) continue;
+  if (!bySess.has(r.sess)) bySess.set(r.sess, []);
+  bySess.get(r.sess)!.push(r);
+}
+for (const [s, list] of bySess) {
+  if (list.length < 2) continue;
+  console.log(`\n${s}：worklog 注入 ${list.length} 次，轮次 ${list.map((x) => x.turn).join(",")}`);
+  for (let i = 1; i < list.length; i++) {
+    const a = list[i - 1].texts.get("worklog") ?? "", b = list[i].texts.get("worklog") ?? "";
+    const same = a === b;
+    // 粗略相似度：公共前缀比例
+    let p = 0; while (p < a.length && p < b.length && a[p] === b[p]) p++;
+    console.log(`   t${list[i - 1].turn}→t${list[i].turn}: ${same ? "完全相同" : `前缀相同 ${p}/${Math.max(a.length, b.length)} 字符 (${((p / Math.max(a.length, b.length)) * 100).toFixed(0)}%)`}`);
+  }
+}
+
+console.log("\n" + "=".repeat(80));
+console.log("④ permission-mode 注入文本是否恒定（静态文案反复注入 = 纯 token 开销）");
+console.log("=".repeat(80));
+const permTexts = new Map<string, number>();
+for (const r of rows) {
+  const t = r.texts.get("perm"); if (!t) continue;
+  permTexts.set(t, (permTexts.get(t) ?? 0) + 1);
+}
+console.log(`不同文案数：${permTexts.size}`);
+for (const [t, n] of permTexts) console.log(`  ${n}× (${t.length} 字符) ${t.replace(/\n/g, " ⏎ ").slice(0, 150)}`);
