+#!/usr/bin/env bun
+/**
+ * 一次性探针 4：repeated-readonly-guard 实测（用完即删）
+ *
+ * 这是唯一「默认开启 + 可强制收尾(yield done)」的行为检测器，风险最高。
+ * events.jsonl 没有 tool_input/output，必须用 raw.jsonl：
+ *   - tool_use 在 response.content
+ *   - 对应 tool_result 在下一次 request 的 new_messages 里（按 tool_use_id 配对）
+ * 用真实 processObservation 重放，逐轮喂 probes。
+ */
+
+import { readFileSync, existsSync, readdirSync } from "node:fs";
+import { join } from "node:path";
+import { homedir } from "node:os";
+
+import {
+  processObservation,
+  createRepeatedReadonlyState,
+  isReadonlyProbeCommand,
+  isReadFamilyTool,
+  makeToolProbeCommand,
+  makeSignature,
+  STUCK_REPEAT_THRESHOLD,
+} from "../src/query/repeated-readonly-guard.ts";
+
+const SESS = join(homedir(), ".sid-code", "trajectories", "sessions");
+
+let totalTurns = 0, remind = 0, terminate = 0;
+const samples: string[] = [];
+const sessHit = new Set<string>();
+// 统计：有多少轮次产生了 probes（即进入检测视野）、最长连续重复次数
+let turnsWithProbes = 0;
+let maxRepeatSeen = 0;
+const repeatHist = new Map<number, number>();
+const probeCmdHist = new Map<string, number>();
+
+for (const id of readdirSync(SESS).sort()) {
+  const p = join(SESS, id, "raw.jsonl");
+  if (!existsSync(p)) continue;
+
+  // 先解析所有行，收集 tool_use（按轮）与 tool_result（按 id）
+  const lines: any[] = [];
+  for (const line of readFileSync(p, "utf8").split("\n")) {
+    if (!line.trim()) continue;
+    try { const o = JSON.parse(line); if (o.type !== "request_sent") lines.push(o); } catch { /* skip */ }
+  }
+  const resultById = new Map<string, string>();
+  for (const o of lines) {
+    for (const m of o.request?.new_messages ?? []) {
+      if (!Array.isArray(m.content)) continue;
+      for (const b of m.content) {
+        if (b.type === "tool_result") {
+          const c = typeof b.content === "string" ? b.content
+            : Array.isArray(b.content) ? b.content.map((x: any) => x.text ?? "").join("\n") : "";
+          resultById.set(b.tool_use_id, c);
+        }
+      }
+    }
+  }
+
+  const st = createRepeatedReadonlyState();
+  let turn = 0;
+  for (const o of lines) {
+    if (!o.response) continue;
+    turn++; totalTurns++;
+    const content = o.response.content ?? [];
+    const probes: Array<{ command: string; output: string }> = [];
+    let other = false;
+    for (const b of content) {
+      if (b.type !== "tool_use") continue;
+      const out = resultById.get(b.id) ?? "";
+      if (b.name === "bash") {
+        const cmd = String(b.input?.command ?? "");
+        if (isReadonlyProbeCommand(cmd)) {
+          probes.push({ command: cmd, output: out });
+          probeCmdHist.set(cmd.slice(0, 60), (probeCmdHist.get(cmd.slice(0, 60)) ?? 0) + 1);
+        } else other = true;
+      } else if (isReadFamilyTool(b.name)) {
+        const c = makeToolProbeCommand(b.name, b.input);
+        probes.push({ command: c, output: out });
+        probeCmdHist.set(c.slice(0, 60), (probeCmdHist.get(c.slice(0, 60)) ?? 0) + 1);
+      } else if (b.name) other = true;
+    }
+    if (probes.length) turnsWithProbes++;
+
+    const before = st.repeatCount;
+    const d = processObservation(st, probes, other);
+    if (st.repeatCount > maxRepeatSeen) maxRepeatSeen = st.repeatCount;
+    if (st.repeatCount >= 2) repeatHist.set(st.repeatCount, (repeatHist.get(st.repeatCount) ?? 0) + 1);
+
+    if (d.action === "remind") {
+      remind++; sessHit.add(id);
+      if (samples.length < 15) samples.push(`REMIND  ${id} t${turn} repeat=${st.repeatCount} cmd=${JSON.stringify((d.command ?? "").slice(0, 80))} out=${JSON.stringify((d.output ?? "").slice(0, 60))}`);
+    } else if (d.action === "terminate") {
+      terminate++; sessHit.add(id);
+      if (samples.length < 15) samples.push(`TERMIN  ${id} t${turn} cmd=${JSON.stringify((d.command ?? "").slice(0, 80))}`);
+    }
+  }
+}
+
+console.log("=".repeat(80));
+console.log(`repeated-readonly-guard 实测（默认开启，THRESHOLD=${STUCK_REPEAT_THRESHOLD}）`);
+console.log("=".repeat(80));
+console.log(`总轮次 ${totalTurns}；其中产生只读探查的轮次 ${turnsWithProbes} (${(turnsWithProbes / totalTurns * 100).toFixed(1)}%)`);
+console.log(`remind ${remind} 次 / terminate ${terminate} 次，涉及 ${sessHit.size} 会话`);
+console.log(`观察到的最长连续相同签名次数：${maxRepeatSeen}（达 ${STUCK_REPEAT_THRESHOLD} 才介入）`);
+console.log(`连续重复次数分布：${[...repeatHist.entries()].sort((a, b) => a[0] - b[0]).map(([k, v]) => `${k}次:${v}轮`).join("  ") || "（无 ≥2 的重复）"}`);
+console.log(`\n最高频的只读探查命令（前 12）：`);
+for (const [c, n] of [...probeCmdHist.entries()].sort((a, b) => b[1] - a[1]).slice(0, 12)) {
+  console.log(`  ${String(n).padStart(4)}×  ${c}`);
+}
+console.log(`\n命中样本：`);
+samples.forEach((s) => console.log("  " + s));
+
+// 反向核查：验证 makeSignature 对"相同命令不同输出"确实区分
+console.log(`\n签名健全性自检：`);
+console.log(`  同命令同输出 → ${makeSignature("git status", "clean") === makeSignature("git status", "clean")}`);
+console.log(`  同命令不同输出 → ${makeSignature("git status", "a") === makeSignature("git status", "b")} (应为 false)`);
