@@ -0,0 +1,89 @@
+#!/usr/bin/env bun
+/**
+ * 一次性探针 7：thinking 分布 + 发散近失分析（用完即删）
+ * 目标：给 THINKING_DIVERGENCE_LEN=20000 一个实测依据（或证明它拍错了）
+ */
+
+import { readFileSync, existsSync, readdirSync } from "node:fs";
+import { join } from "node:path";
+import { homedir } from "node:os";
+import {
+  isThinkingDiverging, pushThinkingLen, measureThinkingLen,
+  THINKING_DIVERGENCE_LEN, THINKING_DIVERGENCE_WINDOW,
+} from "../src/query/thinking-divergence.ts";
+
+const SESS = join(homedir(), ".sid-code", "trajectories", "sessions");
+
+interface S { id: string; lens: number[] }
+const sessions: S[] = [];
+for (const id of readdirSync(SESS).sort()) {
+  const p = join(SESS, id, "raw.jsonl");
+  if (!existsSync(p)) continue;
+  const lens: number[] = [];
+  for (const line of readFileSync(p, "utf8").split("\n")) {
+    if (!line.trim()) continue;
+    let o: any; try { o = JSON.parse(line); } catch { continue; }
+    if (o.type === "request_sent" || !o.response) continue;
+    lens.push(measureThinkingLen(o.response.content ?? []));
+  }
+  if (lens.length) sessions.push({ id, lens });
+}
+
+const all = sessions.flatMap((s) => s.lens);
+const sorted = [...all].sort((a, b) => a - b);
+const pct = (p: number) => sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * p))];
+console.log("=".repeat(80));
+console.log(`thinking 字符数分布（${all.length} 轮，${sessions.length} 会话）`);
+console.log("=".repeat(80));
+console.log(`  p50=${pct(0.5)} p75=${pct(0.75)} p90=${pct(0.9)} p95=${pct(0.95)} p99=${pct(0.99)} max=${sorted[sorted.length - 1]}`);
+console.log(`  当前阈值 THINKING_DIVERGENCE_LEN=${THINKING_DIVERGENCE_LEN}`);
+console.log(`  超过阈值的轮次：${all.filter((v) => v >= THINKING_DIVERGENCE_LEN).length} / ${all.length}`);
+console.log(`  非零 thinking 轮次：${all.filter((v) => v > 0).length}`);
+
+// 找所有"窗口内严格递增"的序列（不看阈值），看末轮值分布 → 判断阈值该定在哪
+console.log("\n" + "=".repeat(80));
+console.log(`严格递增窗口（WINDOW=${THINKING_DIVERGENCE_WINDOW}）出现情况 —— 阈值是唯一拦路条件`);
+console.log("=".repeat(80));
+const monoTails: Array<{ id: string; turn: number; win: number[] }> = [];
+for (const s of sessions) {
+  for (let i = THINKING_DIVERGENCE_WINDOW - 1; i < s.lens.length; i++) {
+    const win = s.lens.slice(i - THINKING_DIVERGENCE_WINDOW + 1, i + 1);
+    let mono = true;
+    for (let k = 1; k < win.length; k++) if (win[k]! <= win[k - 1]!) { mono = false; break; }
+    if (mono && win[0]! > 0) monoTails.push({ id: s.id, turn: i + 1, win });
+  }
+}
+monoTails.sort((a, b) => b.win[b.win.length - 1]! - a.win[a.win.length - 1]!);
+console.log(`严格递增窗口总数：${monoTails.length}`);
+console.log(`其中末轮 ≥${THINKING_DIVERGENCE_LEN}（即真正会触发）：${monoTails.filter((m) => m.win[m.win.length - 1]! >= THINKING_DIVERGENCE_LEN).length}`);
+console.log(`\n末轮最大的 12 个递增窗口（近失排行）：`);
+for (const m of monoTails.slice(0, 12)) {
+  const tail = m.win[m.win.length - 1]!;
+  const gap = THINKING_DIVERGENCE_LEN - tail;
+  console.log(`  ${m.id} t${m.turn}  [${m.win.join(" → ")}]  末轮=${tail}  距阈值差 ${gap} (${(tail / THINKING_DIVERGENCE_LEN * 100).toFixed(1)}%)`);
+}
+
+// 真实重放确认零触发
+let fires = 0;
+for (const s of sessions) {
+  let h: number[] = [];
+  for (const v of s.lens) { h = pushThinkingLen(h, v); if (isThinkingDiverging(h)) fires++; }
+}
+console.log(`\n真实重放 isThinkingDiverging 触发次数：${fires}`);
+
+// 反事实：阈值调低到各候选值时的触发次数（评估误报风险）
+console.log("\n" + "=".repeat(80));
+console.log("反事实：阈值调低后的触发次数（评估是否会误伤正常深推理）");
+console.log("=".repeat(80));
+for (const cand of [8000, 10000, 12000, 15000, 17000, 20000]) {
+  let n = 0; const where: string[] = [];
+  for (const s of sessions) {
+    for (let i = THINKING_DIVERGENCE_WINDOW - 1; i < s.lens.length; i++) {
+      const win = s.lens.slice(i - THINKING_DIVERGENCE_WINDOW + 1, i + 1);
+      let mono = true;
+      for (let k = 1; k < win.length; k++) if (win[k]! <= win[k - 1]!) { mono = false; break; }
+      if (mono && win[win.length - 1]! >= cand) { n++; if (where.length < 4) where.push(`${s.id.slice(-8)}t${i + 1}`); }
+    }
+  }
+  console.log(`  阈值 ${String(cand).padStart(6)} → 触发 ${String(n).padStart(3)} 次  ${where.join(" ")}`);
+}

