diff --git a/src/mcp/oauth-callback-server.ts b/src/mcp/oauth-callback-server.ts
new file mode 100644
index 0000000..a31b337
--- /dev/null
+++ b/src/mcp/oauth-callback-server.ts
@@ -0,0 +1,188 @@
+/**
+ * MCP OAuth 本地回调服务器
+ *
+ * 在 localhost 启动 HTTP 服务器，监听 /callback 路径接收授权码。
+ * 对标 Claude Code oauthPort.ts + performMCPOAuthFlow 中 createServer 片段。
+ *
+ * 设计：
+ * - 随机或指定端口（RFC 8252 §7.3：loopback 重定向可用任意端口）
+ * - CSRF state 校验（授权服务器回传的 state 必须匹配发出时的值）
+ * - 超时 + abort 信号清理
+ * - 仅绑定 127.0.0.1（不暴露到外网）
+ */
+
+import { createServer, type Server } from "node:http";
+import { parse as parseUrl } from "node:url";
+import { getLogger } from "../debug/logger.ts";
+
+/** 端口范围（非 Windows 平台，对标 CC） */
+const PORT_RANGE_MIN = 49152;
+const PORT_RANGE_MAX = 65535;
+const FALLBACK_PORT = 3118;
+const MAX_PORT_ATTEMPTS = 100;
+
+/** 回调服务器句柄 */
+export interface CallbackServerHandle {
+  /** 回调 redirect URI（含端口，如 http://localhost:52341/callback） */
+  redirectUri: string;
+  /** 实际监听端口 */
+  port: number;
+  /**
+   * 等待授权码到达（阻塞 Promise）。
+   * @param expectedState 发出授权请求时生成的 CSRF state
+   * @param timeoutMs 超时毫秒
+   * @param signal 外部 abort 信号
+   */
+  waitForCode(expectedState: string, timeoutMs: number, signal?: AbortSignal): Promise<string>;
+  /** 手动关闭服务器（不论是否已收到回调） */
+  close(): void;
+}
+
+/**
+ * 探测端口是否可用（用 createServer 短暂绑定后释放）。
+ * Bun 下 createServer listen(0) 可直接拿随机端口，但为了与 CC 保持一致的
+ * 「固定端口优先」行为，这里保留显式探测。
+ */
+async function isPortAvailable(port: number): Promise<boolean> {
+  return new Promise((resolve) => {
+    const server = createServer();
+    server.once("error", () => resolve(false));
+    server.listen(port, "127.0.0.1", () => {
+      server.close(() => resolve(true));
+    });
+  });
+}
+
+/** 找到一个空闲端口（配置端口 > 随机尝试 > 回退端口） */
+async function findAvailablePort(configuredPort?: number): Promise<number> {
+  if (configuredPort) {
+    if (await isPortAvailable(configuredPort)) return configuredPort;
+    getLogger().warn("MCP", `配置的 OAuth 回调端口 ${configuredPort} 不可用，回退随机选取`);
+  }
+  const range = PORT_RANGE_MAX - PORT_RANGE_MIN + 1;
+  for (let i = 0; i < MAX_PORT_ATTEMPTS; i++) {
+    const port = PORT_RANGE_MIN + Math.floor(Math.random() * range);
+    if (await isPortAvailable(port)) return port;
+  }
+  if (await isPortAvailable(FALLBACK_PORT)) return FALLBACK_PORT;
+  throw new Error("无可用端口用于 OAuth 回调");
+}
+
+/**
+ * 启动本地 OAuth 回调服务器。
+ * 返回句柄，调用方用 waitForCode 等待授权码，结束后 close。
+ */
+export async function startCallbackServer(configuredPort?: number): Promise<CallbackServerHandle> {
+  const port = await findAvailablePort(configuredPort);
+  const redirectUri = `http://localhost:${port}/callback`;
+
+  let resolveCode: ((code: string) => void) | undefined;
+  let rejectCode: ((err: Error) => void) | undefined;
+  let server: Server | null = null;
+  let closed = false;
+
+  const close = () => {
+    if (closed) return;
+    closed = true;
+    if (server) {
+      server.removeAllListeners();
+      server.on("error", () => {}); // 防 close 后的迟到错误
+      server.close();
+      server = null;
+    }
+  };
+
+  server = createServer((req, res) => {
+    const parsed = parseUrl(req.url || "", true);
+    if (parsed.pathname !== "/callback") {
+      res.writeHead(404, { "Content-Type": "text/plain" });
+      res.end("Not Found");
+      return;
+    }
+
+    const error = parsed.query.error as string | undefined;
+    const errorDesc = parsed.query.error_description as string | undefined;
+    const code = parsed.query.code as string | undefined;
+    const state = parsed.query.state as string | undefined;
+
+    if (error) {
+      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
+      res.end(`<h1>授权失败</h1><p>${escapeHtml(error)}: ${escapeHtml(errorDesc || "")}</p><p>可关闭此窗口。</p>`);
+      close();
+      rejectCode?.(new Error(`OAuth 错误: ${error} - ${errorDesc || ""}`));
+      return;
+    }
+
+    if (!code) {
+      res.writeHead(400, { "Content-Type": "text/html; charset=utf-8" });
+      res.end(`<h1>缺少授权码</h1><p>可关闭此窗口并重试。</p>`);
+      return;
+    }
+
+    // state 传递给 waitForCode 做校验（这里先回复浏览器）
+    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
+    res.end(`<h1>授权成功</h1><p>可关闭此窗口，返回 sid-code。</p>`);
+
+    // resolve（state 校验在 waitForCode 中进行，这里传出 code+state 对）
+    resolveCode?.(`${code}\x00${state || ""}`);
+    close();
+  });
+
+  server.on("error", (err: NodeJS.ErrnoException) => {
+    close();
+    rejectCode?.(new Error(`OAuth 回调服务器错误: ${err.message}`));
+  });
+
+  // 绑定到 127.0.0.1（不暴露）
+  await new Promise<void>((resolve, reject) => {
+    server!.once("error", reject);
+    server!.listen(port, "127.0.0.1", () => resolve());
+  });
+  // 取消事件循环引用——不阻止进程退出
+  server.unref();
+
+  return {
+    redirectUri,
+    port,
+    waitForCode(expectedState: string, timeoutMs: number, signal?: AbortSignal): Promise<string> {
+      return new Promise((resolve, reject) => {
+        resolveCode = (raw: string) => {
+          const [code, state] = raw.split("\x00");
+          if (state !== expectedState) {
+            close();
+            reject(new Error("OAuth state 不匹配（可能是 CSRF 攻击）"));
+            return;
+          }
+          resolve(code);
+        };
+        rejectCode = reject;
+
+        // 超时
+        const timer = setTimeout(() => {
+          close();
+          reject(new Error("等待 OAuth 授权超时"));
+        }, timeoutMs);
+        (timer as any).unref?.();
+
+        // abort 信号
+        if (signal) {
+          if (signal.aborted) {
+            close();
+            reject(new Error("OAuth 授权已取消"));
+            return;
+          }
+          const onAbort = () => {
+            close();
+            reject(new Error("OAuth 授权已取消"));
+          };
+          signal.addEventListener("abort", onAbort, { once: true });
+        }
+      });
+    },
+    close,
+  };
+}
+
+function escapeHtml(s: string): string {
+  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
+}
diff --git a/src/mcp/oauth-lock.ts b/src/mcp/oauth-lock.ts
new file mode 100644
index 0000000..cd7375c
--- /dev/null
+++ b/src/mcp/oauth-lock.ts
@@ -0,0 +1,140 @@
+/**
+ * MCP OAuth token 刷新跨进程互斥锁
+ *
+ * 对标 Claude Code refreshAuthorization 中的 proper-lockfile 用法。sid-code 无
+ * 该依赖，改用「原子 mkdir」实现跨进程锁——mkdir 在 POSIX/Windows 上都是原子的，
+ * 同一目录只能被一个进程成功创建，天然适合做锁。
+ *
+ * 目的：多个 sid-code 实例同时发现 token 过期时，避免并发刷新——并发刷新会让
+ * 先返回的那次刷新作废另一次的 refresh_token（很多授权服务器刷新即轮换）。
+ */
+
+import { mkdirSync, rmdirSync, existsSync, readFileSync, writeFileSync, statSync } from "node:fs";
+import { join } from "node:path";
+import type { MCPServerConfig } from "../config/config.ts";
+import { sidPaths } from "../config/paths.ts";
+import { getServerKey } from "./oauth-storage.ts";
+import { getLogger } from "../debug/logger.ts";
+
+/** 获取锁的最大重试次数 */
+const MAX_LOCK_RETRIES = 5;
+/** 每次重试基础等待（ms），叠加随机抖动 */
+const LOCK_RETRY_BASE_MS = 1000;
+/** 锁过期时间（ms）：超过此时长视为陈旧锁（持有进程崩溃），可强夺 */
+const LOCK_STALE_MS = 30_000;
+
+function lockDir(serverName: string, config: MCPServerConfig): string {
+  const key = getServerKey(serverName, config).replace(/[^a-zA-Z0-9]/g, "_");
+  return join(sidPaths.mcpOAuthLocks(), `${key}.lock`);
+}
+
+function sleep(ms: number): Promise<void> {
+  return new Promise((r) => setTimeout(r, ms));
+}
+
+/** 确保锁根目录存在 */
+function ensureLockRoot(): void {
+  const root = sidPaths.mcpOAuthLocks();
+  if (!existsSync(root)) {
+    mkdirSync(root, { recursive: true });
+  }
+}
+
+/** 尝试获取锁一次：原子 mkdir 成功即拿到；目录已存在且未陈旧则失败 */
+function tryAcquire(dir: string): boolean {
+  try {
+    mkdirSync(dir);
+    // 写入持有者信息（pid + 时间戳）用于陈旧判定
+    try {
+      writeFileSync(join(dir, "owner"), JSON.stringify({ pid: process.pid, ts: Date.now() }));
+    } catch {}
+    return true;
+  } catch (err) {
+    if ((err as NodeJS.ErrnoException).code === "EEXIST") {
+      // 锁已被占——检查是否陈旧
+      if (isStale(dir)) {
+        forceRelease(dir);
+        // 陈旧锁已清，再试一次原子创建
+        try {
+          mkdirSync(dir);
+          try {
+            writeFileSync(join(dir, "owner"), JSON.stringify({ pid: process.pid, ts: Date.now() }));
+          } catch {}
+          return true;
+        } catch {
+          return false;
+        }
+      }
+      return false;
+    }
+    // 其它错误（权限等）当作拿不到锁
+    return false;
+  }
+}
+
+/** 判定锁是否陈旧（持有者超过 LOCK_STALE_MS 未释放，多半是进程崩溃） */
+function isStale(dir: string): boolean {
+  try {
+    const ownerPath = join(dir, "owner");
+    if (existsSync(ownerPath)) {
+      const owner = JSON.parse(readFileSync(ownerPath, "utf-8")) as { pid: number; ts: number };
+      return Date.now() - owner.ts > LOCK_STALE_MS;
+    }
+    // 无 owner 文件，用目录创建时间兜底
+    const st = statSync(dir);
+    return Date.now() - st.ctimeMs > LOCK_STALE_MS;
+  } catch {
+    // 读不到信息，保守视为陈旧（避免永久死锁）
+    return true;
+  }
+}
+
+/** 强制释放锁目录 */
+function forceRelease(dir: string): void {
+  try {
+    const ownerPath = join(dir, "owner");
+    if (existsSync(ownerPath)) {
+      require("node:fs").unlinkSync(ownerPath);
+    }
+    rmdirSync(dir);
+  } catch {
+    // 已被别的进程清掉，忽略
+  }
+}
+
+/**
+ * 在跨进程锁保护下执行 fn。
+ * 拿不到锁时退避重试 MAX_LOCK_RETRIES 次；仍失败则放弃锁直接执行（best-effort，
+ * 对标 CC「proceeding without lock」——宁可偶发并发刷新也不要卡死用户）。
+ */
+export async function withRefreshLock<T>(
+  serverName: string,
+  config: MCPServerConfig,
+  fn: () => Promise<T>,
+): Promise<T> {
+  const log = getLogger();
+  ensureLockRoot();
+  const dir = lockDir(serverName, config);
+
+  let acquired = false;
+  for (let retry = 0; retry < MAX_LOCK_RETRIES; retry++) {
+    if (tryAcquire(dir)) {
+      acquired = true;
+      break;
+    }
+    log.debug("MCP", `${serverName} 刷新锁被占用，等待重试 (${retry + 1}/${MAX_LOCK_RETRIES})`);
+    await sleep(LOCK_RETRY_BASE_MS + Math.random() * LOCK_RETRY_BASE_MS);
+  }
+
+  if (!acquired) {
+    log.warn("MCP", `${serverName} 获取刷新锁失败，无锁执行（best-effort）`);
+  }
+
+  try {
+    return await fn();
+  } finally {
+    if (acquired) {
+      forceRelease(dir);
+    }
+  }
+}
diff --git a/src/mcp/oauth-storage.ts b/src/mcp/oauth-storage.ts
new file mode 100644
index 0000000..f4b7c24
--- /dev/null
+++ b/src/mcp/oauth-storage.ts
@@ -0,0 +1,204 @@
+/**
+ * MCP OAuth 凭据存储
+ *
+ * 持久化远程 MCP 服务器的 OAuth 凭据：access/refresh token、动态注册得到的
+ * client_id/client_secret、以及 discovery 状态（授权服务器 URL / 资源元数据 URL）。
+ * 对标 Claude Code SecureStorageData.mcpOAuth，但 sid-code 无 keychain 依赖，
+ * 落盘到 ~/.sid-code/mcp-oauth.json（文件权限 0600，仅当前用户可读写）。
+ *
+ * Server Key 设计（对标 CC getServerKey）：用 serverName + 配置哈希做键，
+ * 防止「同名但不同 URL/headers」的服务器复用彼此凭据。
+ */
+
+import { createHash } from "node:crypto";
+import { existsSync, readFileSync, writeFileSync, mkdirSync, chmodSync, unlinkSync } from "node:fs";
+import { dirname } from "node:path";
+import type { MCPServerConfig } from "../config/config.ts";
+import { sidPaths } from "../config/paths.ts";
+import { getLogger } from "../debug/logger.ts";
+
+/** 单个 MCP 服务器的 OAuth 凭据条目 */
+export interface MCPOAuthEntry {
+  serverName: string;
+  serverUrl: string;
+  /** access token（可能为空字符串，表示已注册 client 但尚未拿到 token） */
+  accessToken: string;
+  /** refresh token（授权服务器可能不下发） */
+  refreshToken?: string;
+  /** access token 过期的绝对时间戳（ms）。0 表示无 token */
+  expiresAt: number;
+  /** 已授予的 scope（空格分隔） */
+  scope?: string;
+  /** 动态注册（RFC 7591）得到的 client_id，或预配置 client_id */
+  clientId?: string;
+  /** 机密客户端的 client_secret */
+  clientSecret?: string;
+  /** discovery 状态：缓存授权服务器 URL，避免每次刷新都重新 RFC 9728/8414 发现 */
+  discoveryState?: {
+    /** 授权服务器 issuer URL（token/authorize 端点的来源） */
+    authorizationServerUrl: string;
+    /** RFC 9728 受保护资源元数据 URL（401 WWW-Authenticate 带出的） */
+    resourceMetadataUrl?: string;
+  };
+}
+
+/** 存储文件结构 */
+interface OAuthStorageData {
+  /** serverKey → 凭据条目 */
+  mcpOAuth: Record<string, MCPOAuthEntry>;
+}
+
+/**
+ * 为服务器生成稳定的存储键：serverName | sha256(type+url+headers)[:16]。
+ * 配置变化（换 URL / 换 header）会产生新键，强制重新授权，避免凭据错配。
+ * 对标 CC getServerKey。
+ */
+export function getServerKey(serverName: string, config: MCPServerConfig): string {
+  const configJson = JSON.stringify({
+    transport: config.transport,
+    url: config.url ?? "",
+    headers: config.headers ?? {},
+  });
+  const hash = createHash("sha256").update(configJson).digest("hex").substring(0, 16);
+  return `${serverName}|${hash}`;
+}
+
+/** 读取整个存储文件（不存在或损坏时返回空结构） */
+function readStorage(): OAuthStorageData {
+  const path = sidPaths.mcpOAuth();
+  if (!existsSync(path)) {
+    return { mcpOAuth: {} };
+  }
+  try {
+    const raw = readFileSync(path, "utf-8");
+    const parsed = JSON.parse(raw) as Partial<OAuthStorageData>;
+    return { mcpOAuth: parsed.mcpOAuth ?? {} };
+  } catch (err) {
+    getLogger().warn("MCP", `OAuth 存储文件解析失败，已忽略: ${(err as Error).message}`);
+    return { mcpOAuth: {} };
+  }
+}
+
+/** 原子写入存储文件，权限收紧到 0600 */
+function writeStorage(data: OAuthStorageData): void {
+  const path = sidPaths.mcpOAuth();
+  const dir = dirname(path);
+  if (!existsSync(dir)) {
+    mkdirSync(dir, { recursive: true });
+  }
+  // 先写临时文件再 rename，避免并发写出现半截文件
+  const tmpPath = `${path}.tmp-${process.pid}`;
+  writeFileSync(tmpPath, JSON.stringify(data, null, 2), { mode: 0o600 });
+  // Bun/Node 的 renameSync 在同目录下是原子的
+  try {
+    // 用 fs.renameSync —— 同分区原子替换
+    require("node:fs").renameSync(tmpPath, path);
+  } catch {
+    // 回退：直接覆盖写
+    writeFileSync(path, JSON.stringify(data, null, 2), { mode: 0o600 });
+    try { unlinkSync(tmpPath); } catch {}
+  }
+  // 双保险：确保权限位正确（部分平台 writeFile 的 mode 受 umask 影响）
+  try { chmodSync(path, 0o600); } catch {}
+}
+
+/** 读取指定服务器的 OAuth 凭据条目 */
+export function getOAuthEntry(serverName: string, config: MCPServerConfig): MCPOAuthEntry | undefined {
+  const key = getServerKey(serverName, config);
+  return readStorage().mcpOAuth[key];
+}
+
+/**
+ * 合并更新指定服务器的 OAuth 凭据条目（浅合并到现有条目）。
+ * 始终补齐 serverName / serverUrl / accessToken / expiresAt 必填字段。
+ */
+export function updateOAuthEntry(
+  serverName: string,
+  config: MCPServerConfig,
+  patch: Partial<MCPOAuthEntry>,
+): void {
+  const key = getServerKey(serverName, config);
+  const data = readStorage();
+  const existing = data.mcpOAuth[key];
+  data.mcpOAuth[key] = {
+    ...existing,
+    ...patch,
+    // 必填字段兜底：优先用 patch，其次现有值，最后默认值
+    serverName,
+    serverUrl: config.url ?? existing?.serverUrl ?? "",
+    accessToken: patch.accessToken ?? existing?.accessToken ?? "",
+    expiresAt: patch.expiresAt ?? existing?.expiresAt ?? 0,
+  };
+  writeStorage(data);
+}
+
+/** 保存 token（来自授权码交换或刷新） */
+export function saveTokens(
+  serverName: string,
+  config: MCPServerConfig,
+  tokens: { access_token: string; refresh_token?: string; expires_in?: number; scope?: string },
+): void {
+  updateOAuthEntry(serverName, config, {
+    accessToken: tokens.access_token,
+    refreshToken: tokens.refresh_token,
+    // expires_in 缺省按 1 小时算（OAuth 2.1 推荐但非强制下发）
+    expiresAt: Date.now() + (tokens.expires_in ?? 3600) * 1000,
+    scope: tokens.scope,
+  });
+}
+
+/** 保存动态注册得到的 client 信息 */
+export function saveClientInformation(
+  serverName: string,
+  config: MCPServerConfig,
+  client: { client_id: string; client_secret?: string },
+): void {
+  updateOAuthEntry(serverName, config, {
+    clientId: client.client_id,
+    clientSecret: client.client_secret,
+  });
+}
+
+/** 保存 discovery 状态（授权服务器 URL 等） */
+export function saveDiscoveryState(
+  serverName: string,
+  config: MCPServerConfig,
+  state: { authorizationServerUrl: string; resourceMetadataUrl?: string },
+): void {
+  updateOAuthEntry(serverName, config, { discoveryState: state });
+}
+
+/**
+ * 清除指定服务器的凭据。
+ * - scope='tokens'：仅清 token（保留 client 注册信息与 discovery，下次免重新注册）
+ * - scope='all'：删除整个条目
+ */
+export function clearOAuthEntry(
+  serverName: string,
+  config: MCPServerConfig,
+  scope: "all" | "tokens" = "all",
+): void {
+  const key = getServerKey(serverName, config);
+  const data = readStorage();
+  const entry = data.mcpOAuth[key];
+  if (!entry) return;
+
+  if (scope === "all") {
+    delete data.mcpOAuth[key];
+  } else {
+    entry.accessToken = "";
+    entry.refreshToken = undefined;
+    entry.expiresAt = 0;
+  }
+  writeStorage(data);
+}
+
+/**
+ * 判断「已探测过 OAuth 但当前无任何可用凭据」的状态。
+ * 这种状态下连接必定 401，唯一出路是用户重新走授权流程。
+ * 对标 CC hasMcpDiscoveryButNoToken。
+ */
+export function hasDiscoveryButNoToken(serverName: string, config: MCPServerConfig): boolean {
+  const entry = getOAuthEntry(serverName, config);
+  return entry !== undefined && !entry.accessToken && !entry.refreshToken;
+}
