+/**
+ * 中断路径消息历史完整性测试 — D1-2
+ *
+ * 本次 bug（2026-06-04 deepseek 第 19 次 API call 触发 400）的真实路径：
+ *   assistant tool_calls 已 addMessage → executeTools 被 AbortError 切开 →
+ *   loop.ts 的 catch 兜底必须补齐 tool_result，使 ctxMgr.getMessages() 无孤儿。
+ *
+ * 当前零覆盖（tool-result-invariant.test.ts 只测 executeTools 单函数，
+ * plan-approval-ordering.test.ts 重新实现了 loop 步骤而非跑真实 loop）。
+ * 本测试直接驱动**真实 AgentLoopRunner.run()** + 真实 ContextManager，
+ * 让 loop.ts:591-607 的 catch 真正执行，再用 D1-4 共享不变量断言无孤儿。
+ *
+ * fix_type: core_code（L3，测试）
+ */
+
+import { describe, test, expect } from "bun:test";
+import { AgentLoopRunner, type AgentLoopDeps } from "../../src/agent/loop.ts";
+import { Manager as ContextManager } from "../../src/context/manager.ts";
+import { Registry as ToolRegistry } from "../../src/tool/registry.ts";
+import { ModelFallback } from "../../src/llm/fallback.ts";
+import { ThinkingManager } from "../../src/llm/thinking.ts";
+import { SessionState } from "../../src/session/state.ts";
+import type { Provider } from "../../src/llm/provider.ts";
+import type {
+  StreamEvent,
+  AccumulatedResponse,
+  ContentBlock,
+  Message,
+} from "../../src/llm/types.ts";
+import { checkMessageHistoryIntegrity } from "../../src/agent/message-invariants.ts";
+
+/** 最小 Provider：sendMessageStream 永远返回一个含 2 个 tool_use 的响应 */
+function makeToolUseProvider(): Provider {
+  const provider: any = {
+    name: () => "mock",
+    defaultModel: () => "mock-model",
+    capabilities: () => ({
+      streaming: true,
+      tools: true,
+      thinking: false,
+      vision: false,
+      promptCaching: false,
+      parallelToolCalls: true,
+    }),
+    // eslint-disable-next-line require-yield
+    async *sendMessageStream(): AsyncIterable<StreamEvent> {
+      // 真实 loop 不直接消费这个流（processStream 被我们 mock），
+      // 但 fallback.executeWithFallback 会调用它拿 stream 对象，故需可迭代。
+      yield { type: "message_stop" };
+    },
+  };
+  return provider as Provider;
+}
+
+/** 构造一个会被中断的 loop deps */
+function makeDeps(opts: {
+  ctxMgr: ContextManager;
+  toolResponse: ContentBlock[];
+  executeTools: (content: ContentBlock[]) => Promise<{ results: ContentBlock[]; followup?: ContentBlock[] }>;
+}): AgentLoopDeps {
+  const config: any = {
+    provider: "mock",
+    model: "mock-model",
+    maxTokens: 4096,
+    maxTurns: 10,
+  };
+
+  // processStream 直接返回预设的 tool_use 响应（不真正解析流）
+  const processStream = async (
+    _stream: AsyncIterable<StreamEvent>,
+    _onText?: (t: string) => void,
+  ): Promise<AccumulatedResponse> => {
+    return {
+      role: "assistant",
+      content: opts.toolResponse,
+      stopReason: "tool_use",
+      usage: { inputTokens: 10, outputTokens: 5 },
+    };
+  };
+
+  return {
+    config,
+    provider: makeToolUseProvider(),
+    ctxMgr: opts.ctxMgr,
+    toolRegistry: new ToolRegistry(),
+    sessionState: new SessionState("test-session-d12"),
+    fallback: new ModelFallback(),
+    thinkingMgr: new ThinkingManager(false),
+    executeTools: opts.executeTools,
+    processStream,
+    autoCompact: async () => {},
+    handleContextOverflow: () => null,
+    getAbortSignal: () => undefined,
+  };
+}
+
+/** 收集 callbacks（只关心是否完成 / 异常） */
+function makeCallbacks() {
+  return {
+    onStreamText: () => {},
+    onToolStart: () => {},
+    onToolEnd: () => {},
+    onCompact: () => {},
+    onComplete: () => {},
+  };
+}
+
+describe("D1-2 — 中断路径消息历史完整性", () => {
+  test("executeTools 抛 AbortError：loop catch 兜底后 ctxMgr 无孤儿 tool_use", async () => {
+    const ctxMgr = new ContextManager({ maxTokens: 100_000 });
+
+    const toolResponse: ContentBlock[] = [
+      { type: "text", text: "我需要读两个文件" },
+      { type: "tool_use", id: "tu_1", name: "read", input: { file: "a.ts" } },
+      { type: "tool_use", id: "tu_2", name: "read", input: { file: "b.ts" } },
+    ];
+
+    // 模拟中断：executeTools 在执行过程中被 AbortError 切开（本次 bug 的真实触发）
+    const executeTools = async () => {
+      const e = new Error("aborted");
+      e.name = "AbortError";
+      throw e;
+    };
+
+    const runner = new AgentLoopRunner(makeDeps({ ctxMgr, toolResponse, executeTools }));
+
+    // run 会因 AbortError 上抛（loop.ts:606 throw err），catch 它
+    let thrown: unknown = null;
+    try {
+      await runner.run("帮我读文件", makeCallbacks());
+    } catch (e) {
+      thrown = e;
+    }
+
+    // AbortError 应被上抛
+    expect(thrown).not.toBeNull();
+    expect((thrown as Error).name).toBe("AbortError");
+
+    // 关键不变量：catch 兜底（yieldMissingToolResults）后，消息历史无孤儿
+    const messages: Message[] = ctxMgr.getMessages();
+    const integrity = checkMessageHistoryIntegrity(messages);
+    expect(integrity.intact).toBe(true);
+    expect(integrity.orphans).toHaveLength(0);
+
+    // 进一步坐实：assistant 的 tu_1/tu_2 都有对应 tool_result
+    const resultIds = messages
+      .filter(m => m.role === "user")
+      .flatMap(m => m.content)
+      .filter((b): b is Extract<ContentBlock, { type: "tool_result" }> => b.type === "tool_result")
+      .map(b => b.tool_use_id)
+      .sort();
+    expect(resultIds).toContain("tu_1");
+    expect(resultIds).toContain("tu_2");
+  });
+
+  test("executeTools 抛普通异常：catch 兜底后同样无孤儿", async () => {
+    const ctxMgr = new ContextManager({ maxTokens: 100_000 });
+
+    const toolResponse: ContentBlock[] = [
+      { type: "tool_use", id: "x_1", name: "edit", input: {} },
+    ];
+
+    const executeTools = async () => {
+      throw new Error("工具执行炸了（非 abort）");
+    };
+
+    const runner = new AgentLoopRunner(makeDeps({ ctxMgr, toolResponse, executeTools }));
+
+    let thrown: unknown = null;
+    try {
+      await runner.run("改个文件", makeCallbacks());
+    } catch (e) {
+      thrown = e;
+    }
+    expect(thrown).not.toBeNull();
+
+    const integrity = checkMessageHistoryIntegrity(ctxMgr.getMessages());
+    expect(integrity.intact).toBe(true);
+  });
+});
diff --git a/tests/llm/provider-protocol-contract.test.ts b/tests/llm/provider-protocol-contract.test.ts
new file mode 100644
index 0000000..56abfe6
--- /dev/null
+++ b/tests/llm/provider-protocol-contract.test.ts
@@ -0,0 +1,118 @@
+/**
+ * Provider 协议契约测试套件 — D2-1
+ *
+ * 不变量：所有 OpenAI 兼容 provider（openai / deepseek / ollama）在发送含孤儿 tool_use
+ * 的脏历史时，D1-1 关卡（guardOutgoingMessages，接在 sendMessageStream /
+ * sendMessageNonStreaming 入口）必须拦截——strict 模式抛 MessageHistoryViolationError，
+ * 且在真正 fetch 之前就抛（不打网络）。
+ *
+ * 覆盖 RL-011 的 ≥3 家 provider。DeepSeek 在 sid-code 里就是自定义 baseURL 的
+ * OpenAIProvider（registry.ts:146），故用 OpenAIProvider + deepseek baseURL 表示。
+ *
+ * fix_type: infra_bug（L1）
+ */
+
+import { describe, test, expect, afterEach } from "bun:test";
+import { OpenAIProvider } from "../../src/llm/openai.ts";
+import { OllamaProvider } from "../../src/llm/ollama.ts";
+import type { Provider } from "../../src/llm/provider.ts";
+import type { SendParams, Message } from "../../src/llm/types.ts";
+import { MessageHistoryViolationError } from "../../src/agent/message-invariants.ts";
+
+/** 构造一条含孤儿 tool_use 的脏历史（c2 缺 tool_result） */
+function dirtyHistory(): Message[] {
+  return [
+    { role: "user", content: [{ type: "text", text: "task" }] },
+    {
+      role: "assistant",
+      content: [
+        { type: "tool_use", id: "c1", name: "read", input: {} },
+        { type: "tool_use", id: "c2", name: "boom", input: {} },
+      ],
+    },
+    { role: "user", content: [{ type: "tool_result", tool_use_id: "c1", content: "ok" }] },
+    // c2 的 tool_result 缺失 → 孤儿
+  ];
+}
+
+/** 干净历史（基线对照） */
+function cleanHistory(): Message[] {
+  return [
+    {
+      role: "assistant",
+      content: [{ type: "tool_use", id: "c1", name: "read", input: {} }],
+    },
+    { role: "user", content: [{ type: "tool_result", tool_use_id: "c1", content: "ok" }] },
+  ];
+}
+
+function sendParams(messages: Message[]): SendParams {
+  return { model: "test-model", messages, maxTokens: 1024 };
+}
+
+/** 被测 provider 矩阵：覆盖 RL-011 的 ≥3 家 OpenAI 兼容 provider */
+const PROVIDERS: Array<{ label: string; make: () => Provider }> = [
+  { label: "openai", make: () => new OpenAIProvider("sk-test", "gpt-4o", "https://api.openai.com/v1") },
+  {
+    label: "deepseek（自定义 baseURL 的 OpenAIProvider）",
+    make: () => new OpenAIProvider("sk-test", "deepseek-v4-pro", "https://api.deepseek.com/v1"),
+  },
+  { label: "ollama", make: () => new OllamaProvider("llama3", "http://localhost:11434/v1") },
+];
+
+afterEach(() => {
+  delete process.env.SID_CODE_PROTOCOL_STRICT;
+});
+
+describe("D2-1 — Provider 协议契约（孤儿历史发送前拦截）", () => {
+  for (const { label, make } of PROVIDERS) {
+    test(`[${label}] strict 模式：脏历史在 sendMessageStream 入口被拦截（不打网络）`, async () => {
+      process.env.SID_CODE_PROTOCOL_STRICT = "1";
+      const provider = make();
+
+      let thrown: unknown = null;
+      try {
+        // 消费 async generator 才会执行 body；guard 在 convertMessages 之前，
+        // 故首个 next() 就应抛 —— 早于任何 fetch。
+        const it = provider.sendMessageStream(sendParams(dirtyHistory()));
+        await it[Symbol.asyncIterator]().next();
+      } catch (e) {
+        thrown = e;
+      }
+      expect(thrown).toBeInstanceOf(MessageHistoryViolationError);
+      const err = thrown as MessageHistoryViolationError;
+      expect(err.detail.orphans.map(o => o.id)).toContain("c2");
+    });
+
+    test(`[${label}] strict 模式：脏历史在 sendMessageNonStreaming 入口被拦截`, async () => {
+      process.env.SID_CODE_PROTOCOL_STRICT = "1";
+      const provider = make() as any;
+
+      let thrown: unknown = null;
+      try {
+        await provider.sendMessageNonStreaming(sendParams(dirtyHistory()));
+      } catch (e) {
+        thrown = e;
+      }
+      expect(thrown).toBeInstanceOf(MessageHistoryViolationError);
+    });
+
+    test(`[${label}] 非 strict：脏历史不抛（降级告警+落盘，由 sentinel 单测覆盖落盘）`, async () => {
+      // 不设 SID_CODE_PROTOCOL_STRICT → 默认非 strict
+      const provider = make();
+      // 干净历史下 guard 静默通过；脏历史非 strict 下也不抛（但会落盘）。
+      // 这里验证"不抛"——真正 fetch 会因 baseURL 不可达而失败，
+      // 但 guard 本身不应在非 strict 下中断流程。用干净历史确认 guard 放行不抛。
+      let guardThrew = false;
+      try {
+        const it = provider.sendMessageStream(sendParams(cleanHistory()));
+        // 只取首个事件；干净历史 guard 必放行（之后的 fetch error 由流内 yield error 事件处理，不抛）
+        await it[Symbol.asyncIterator]().next();
+      } catch (e) {
+        // 干净历史不应因 guard 抛 MessageHistoryViolationError
+        if (e instanceof MessageHistoryViolationError) guardThrew = true;
+      }
+      expect(guardThrew).toBe(false);
+    });
+  }
+});

