diff --git a/src/tool/ask-user-question-bridge.ts b/src/tool/ask-user-question-bridge.ts
new file mode 100644
index 0000000..7c98e81
--- /dev/null
+++ b/src/tool/ask-user-question-bridge.ts
@@ -0,0 +1,94 @@
+/**
+ * AskUserQuestion 桥接模块
+ *
+ * 解决"工具执行时没有 TUI 句柄"的问题：tool-executor 调 `tool.execute(input, signal)`，
+ * 不向工具传任何 TUI 通道。AskUserQuestionTool 需要在执行中途唤起交互式选择题 UI 并阻塞
+ * 等待用户作答——和权限确认/Shell 确认/Plan 审批同构（app.ts 用 setTUIConfirmCallback
+ * 等回调把"请求"投影成 TUI 状态）。
+ *
+ * 本模块是一个模块级单例 handler 注册表（对标 agent/message-queue.ts 的桥接思路）：
+ * - TUI 模式：app.ts 在 doInit 里调 setAskUserQuestionHandler 注入真正弹窗的实现。
+ * - headless/SDK/CI 模式：无人注入 handler → askUserQuestion 返回 { status: "unavailable" }，
+ *   工具据此告知模型"当前无法向用户提问，请用最合理的默认继续"，绝不阻塞无头进程。
+ *
+ * 对标 claude-code src/tools/AskUserQuestionTool/AskUserQuestionTool.tsx
+ * + components/permissions/AskUserQuestionPermissionRequest。
+ */
+
+/** 单个选项 */
+export interface AskQuestionOption {
+  /** 显示给用户的选项文本（1-5 词） */
+  label: string;
+  /** 选项说明 / 权衡解释（可选） */
+  description?: string;
+}
+
+/** 单个问题 */
+export interface AskQuestion {
+  /** 完整问题文本，以问号结尾 */
+  question: string;
+  /** chip/tag 显示的短标签 */
+  header: string;
+  /** 2-4 个候选项（UI 会自动追加"其他"以支持自定义输入） */
+  options: AskQuestionOption[];
+  /** 是否允许多选（默认 false） */
+  multiSelect?: boolean;
+}
+
+/** 一次提问请求（1-4 个问题） */
+export interface AskUserQuestionRequest {
+  questions: AskQuestion[];
+}
+
+/**
+ * 提问结果。
+ * - answered：用户作答，answers 按"问题文本 → 答案"映射（多选答案以 ", " 连接）。
+ * - cancelled：用户主动放弃回答（ESC）。
+ * - unavailable：当前无交互通道（headless/SDK/CI），无法提问。
+ */
+export type AskUserQuestionResult =
+  | { status: "answered"; answers: Record<string, string> }
+  | { status: "cancelled" }
+  | { status: "unavailable" };
+
+/** TUI 注入的提问处理器 */
+export type AskUserQuestionHandler = (
+  request: AskUserQuestionRequest,
+  signal?: AbortSignal,
+) => Promise<AskUserQuestionResult>;
+
+let handler: AskUserQuestionHandler | null = null;
+
+/**
+ * 注册提问处理器（TUI 模式由 app.ts 注入）。
+ * 返回反注册函数，便于会话结束 / 测试清理。
+ */
+export function setAskUserQuestionHandler(h: AskUserQuestionHandler | null): () => void {
+  handler = h;
+  return () => {
+    if (handler === h) handler = null;
+  };
+}
+
+/** 当前是否存在可用的提问通道（交互模式判定）。 */
+export function hasAskUserQuestionHandler(): boolean {
+  return handler !== null;
+}
+
+/**
+ * 发起一次提问。工具层调用入口。
+ *
+ * 无 handler（headless）时立即返回 unavailable，不阻塞；handler 抛错时同样降级为
+ * unavailable，保证工具永远拿得到结果、不会把异常冒泡成孤儿 tool_use。
+ */
+export async function askUserQuestion(
+  request: AskUserQuestionRequest,
+  signal?: AbortSignal,
+): Promise<AskUserQuestionResult> {
+  if (!handler) return { status: "unavailable" };
+  try {
+    return await handler(request, signal);
+  } catch {
+    return { status: "unavailable" };
+  }
+}
diff --git a/src/tool/ask-user-question.ts b/src/tool/ask-user-question.ts
new file mode 100644
index 0000000..715615e
--- /dev/null
+++ b/src/tool/ask-user-question.ts
@@ -0,0 +1,157 @@
+/**
+ * AskUserQuestion 工具
+ *
+ * 让模型在需要用户决策时，向用户抛出**结构化选择题**（而非在正文里夹一句问话等用户
+ * 自由回答）：每题 2-4 个候选项，用户用键盘选择，答案结构化回灌给模型。适用于
+ * 方案选型、歧义澄清、关键取舍等"继续往下做之前必须由人拍板"的场景。
+ *
+ * 设计对标 claude-code src/tools/AskUserQuestionTool/AskUserQuestionTool.tsx：
+ * - shouldDefer：长尾低频工具，由 ToolSearch 按需调出，不占首轮上下文。
+ * - 交互通过 ask-user-question-bridge 唤起 TUI 弹窗（headless 模式自动降级）。
+ * - 结果格式化为 `「问题」→「答案」` 文本回灌模型，多选答案以 ", " 连接。
+ *
+ * fix_type: new_module
+ */
+
+import type { LegacyTool as Tool, LegacyToolResult as ToolResult } from "./types.ts";
+import { z } from "zod/v4";
+import { lazySchema } from "../sdk/lazy-schema.ts";
+import {
+  askUserQuestion,
+  type AskQuestion,
+} from "./ask-user-question-bridge.ts";
+
+/** 单题最多候选项数（对标 cc 的 2-4） */
+const MAX_OPTIONS = 4;
+const MIN_OPTIONS = 2;
+/** 一次最多提问数（对标 cc 的 1-4） */
+const MAX_QUESTIONS = 4;
+
+const askUserQuestionSchema = lazySchema(() =>
+  z.object({
+    questions: z
+      .array(
+        z.object({
+          question: z
+            .string()
+            .describe("完整问题文本，应以问号结尾，清晰具体"),
+          header: z
+            .string()
+            .describe("极短标签（≤12 字符），作为该问题的分类 chip 显示，如 '认证方式' '数据库'"),
+          options: z
+            .array(
+              z.object({
+                label: z.string().describe("选项显示文本（1-5 词，简洁且互斥）"),
+                description: z
+                  .string()
+                  .optional()
+                  .describe("该选项的说明或权衡解释（可选）"),
+              }),
+            )
+            .min(MIN_OPTIONS)
+            .max(MAX_OPTIONS)
+            .describe(`${MIN_OPTIONS}-${MAX_OPTIONS} 个候选项。无需提供"其他"选项——UI 会自动追加，允许用户自定义输入`),
+          multiSelect: z
+            .boolean()
+            .optional()
+            .describe("是否允许多选（选项之间不互斥时设为 true，默认 false）"),
+        }),
+      )
+      .min(1)
+      .max(MAX_QUESTIONS)
+      .describe(`要向用户提出的问题列表（1-${MAX_QUESTIONS} 个）`),
+  }),
+);
+
+export class AskUserQuestionTool implements Tool {
+  readonly zodSchema = askUserQuestionSchema();
+  /** 长尾低频工具：仅在需要用户拍板时使用，延迟加载，由 tool_search 按需调出 */
+  readonly shouldDefer = true;
+  readonly searchHint = "ask user question choice clarify decision 提问 选择 澄清 决策 选型";
+
+  name(): string {
+    return "ask_user_question";
+  }
+
+  description(): string {
+    return `向用户提出结构化选择题，收集决策。当你遇到只有用户能拍板的关键岔路口时使用——而不是在回复正文里夹一句问话。
+
+## 何时使用
+- 方案选型：多种合理实现路径，需要用户选一种（如 OAuth vs JWT、Redis vs 内存缓存）
+- 歧义澄清：需求有多种理解，继续做之前必须确认
+- 关键取舍：性能/可维护性/工期等维度需要用户权衡
+- 范围确认：要改动的边界不清晰，需用户圈定
+
+## 何时不使用
+- 你能从代码/上下文/常理推断出合理默认 → 直接做，事后说明，别打断用户
+- 只是想确认"我这样做对吗" → 不要为寻求认可而提问
+- 信息查询类问题 → 自己查（读代码 / 搜索 / 联网），不要问用户
+- 纯偏好且有约定俗成默认（命名/格式/默认值）→ 选合理项并注明
+
+## 用法
+- 一次可提 1-4 个问题，每题 2-4 个候选项。
+- 每个选项给简短 label + 可选 description（解释这个选项意味着什么、有何权衡）。
+- 若推荐某个选项，把它放在第一个，并在 label 末尾标注"(推荐)"。
+- 选项之间不互斥时设 multiSelect: true（允许用户多选）。
+- 无需提供"其他"选项——UI 会自动追加，允许用户自定义输入。
+
+用户作答后，答案会以"问题 → 答案"的形式回灌给你。请严格按用户的选择继续，不要无视用户的决策。`;
+  }
+
+  inputSchema(): Record<string, unknown> {
+    return z.toJSONSchema(askUserQuestionSchema()) as Record<string, unknown>;
+  }
+
+  /** 只读：不改动任何文件 / 状态，仅收集用户输入 */
+  readOnly(): boolean {
+    return true;
+  }
+
+  /**
+   * 非并发安全：交互式弹窗必须独占——多个提问同时弹出会争抢键盘焦点、互相覆盖。
+   * 串行执行保证一次只弹一个问卷。
+   */
+  isConcurrencySafe(): boolean {
+    return false;
+  }
+
+  async execute(input: unknown, signal?: AbortSignal): Promise<ToolResult> {
+    const params = input as { questions?: AskQuestion[] };
+
+    if (!Array.isArray(params?.questions) || params.questions.length === 0) {
+      return {
+        output:
+          "questions 必须是非空数组。格式: { questions: [{ question, header, options: [{ label, description? }], multiSelect? }] }",
+        isError: true,
+      };
+    }
+
+    const result = await askUserQuestion({ questions: params.questions }, signal);
+
+    if (result.status === "unavailable") {
+      // headless/SDK/CI 模式：无交互通道。明确告知模型"无法向用户提问"，
+      // 让它退回到自行选择最合理默认并继续，而不是误以为用户拒绝或卡住。
+      return {
+        output:
+          "当前运行环境无法向用户提问（非交互模式 / 无 TUI）。请基于现有上下文选择最合理的默认方案继续推进，并在最终回复中说明你的选择与理由。",
+        isError: false,
+      };
+    }
+
+    if (result.status === "cancelled") {
+      return {
+        output:
+          "用户取消了回答（未作选择）。请不要重复追问同样的问题；基于现有信息选择最合理的默认方案继续，或在回复中说明你需要的信息。",
+        isError: false,
+      };
+    }
+
+    // answered：把"问题 → 答案"格式化回灌模型
+    const lines: string[] = ["用户已作答："];
+    for (const q of params.questions) {
+      const answer = result.answers[q.question];
+      lines.push(`· ${q.question} → ${answer ?? "(未作答)"}`);
+    }
