+/**
+ * 结构化任务清单测试（P1-5 路线 A）
+ * 覆盖 store 依赖图/成环检测 + 四个工具（task_create/task_update/task_get/task_list）行为。
+ */
+import { describe, test, expect, beforeEach } from "bun:test";
+import {
+  createStructuredTask,
+  getStructuredTask,
+  getAllStructuredTasks,
+  updateStructuredTask,
