+  // 让 `git *` 同时匹配 `git add` 和裸 `git`（对齐 `git:*` 前缀语义）。
+  // 多通配符模式（如 `* run *`）排除——否则末尾通配符可选会误匹配 `npm run`（无尾参）。
+  const unescapedStarCount = (processed.match(/\*/g) || []).length;
