+
+// ============================================================
+// 往返保真（本文件最重要的一组）
+// ============================================================
+describe("VCR · 往返保真（经生产 processStream）", () => {
+  test("录制 → 回放 → processStream 累加，与原始录制逐字段相等", async () => {
+    const turns = parseRawJsonl(SAMPLE_RAW);
+    const p = new ReplayProvider(turns);
