+/**
+ * 临时验收脚本（PR1）——用完即删，不入库。
+ *
+ * 走**生产函数** initTelemetrySystem（内部 probe.registerHooks）+ 真实 HookSystem
+ * + 真实 JsonlExporter 落盘，按两种顺序各跑一遍，对比 traces.jsonl 的实际产物。
+ * 落盘目录由 OUT_DIR 指定（不碰 ~/.sid-code/）。
+ */
+import { initTelemetrySystem } from "@sid-code/core/query/init-helpers.ts";
+import { HookSystem } from "@sid-code/core/hook/system.ts";
+import { SessionState } from "@sid-code/core/session/state.ts";
+import { shutdownTelemetry } from "@sid-code/core/telemetry/index.ts";
+
+const outDir = process.env.OUT_DIR!;
+const order = process.env.ORDER!; // "fixed" | "buggy"
+const MODEL = "glm-5.3";
+
+const config: any = {
+  model: MODEL,
+  provider: "openai",
+  telemetry: { enabled: true, exporters: [{ type: "jsonl", options: { outputDir: outDir } }] },
+};
+const hookSystem = new HookSystem();
+const sessionState = new SessionState("pr1-e2e-" + order);
+
+const fire = () => hookSystem.fireSessionStartEvent("startup", { model: MODEL });
+
+// 缺陷顺序：先 fire 再注册（复刻修复前 app.ts）；修复顺序：先注册再 fire
+if (order === "buggy") await fire();
+await initTelemetrySystem(config, hookSystem, sessionState, undefined);
+if (order === "fixed") await fire();
+
+// 完整一轮模型调用（AfterModel 必须带 usage，否则 chat span 走不到 end）
+const llmRequest: any = { model: MODEL, messages: [], system: "" };
+await hookSystem.fireBeforeModelEvent(llmRequest);
+await hookSystem.fireAfterModelEvent(llmRequest, {
+  text: "ok",
+  usage: { inputTokens: 100, outputTokens: 20 },
+} as any);
+
+// 一次工具调用 → execute_tool span
+await hookSystem.firePostToolUseEvent("bash", { command: "ls" }, { output: "x" });
+
+await hookSystem.fireSessionEndEvent("exit", {
+  total_cost_usd: 0,
+  total_tokens_sent: 100,
+  total_tokens_received: 20,
+});
+await shutdownTelemetry(); // 真实 flush 路径

