--- /dev/null
+++ b/src/sdk/lazy-schema.ts
@@ -0,0 +1,22 @@
+/**
+ * lazySchema — 延迟构造 Zod Schema
+ *
+ * 解决两个问题：
+ * 1. Schema 之间的循环引用（A 引用 B、B 引用 A 时直接构造会死循环）
+ * 2. 启动性能（未使用的 Schema 不会被构造）
+ *
+ * 对齐 Claude Code 的 lazySchema() 设计：所有 SDK Schema 用工厂函数包装，
+ * 首次调用时构造并缓存，后续调用返回缓存实例。
+ */
+
+import type { z } from "zod";
+
+export function lazySchema<T extends z.ZodTypeAny>(factory: () => T): () => T {
+  let cached: T | undefined;
+  return () => {
+    if (!cached) {
+      cached = factory();
+    }
+    return cached;
+  };
+}
diff --git a/src/sdk/mcp-bridge.ts b/src/sdk/mcp-bridge.ts
new file mode 100644
index 0000000..07cbaf6
--- /dev/null
+++ b/src/sdk/mcp-bridge.ts
@@ -0,0 +1,120 @@
+/**
+ * SDK MCP 工具桥接（SdkControlTransport）
+ *
+ * 让 SDK 宿主进程注册的自定义 MCP 工具能被 CLI 子进程调用：
+ *
+ *   SDK 宿主进程                              CLI 子进程
+ *   ┌──────────────────────┐                ┌──────────────────────────┐
+ *   │  SDK MCP Server      │                │  MCP Client (sid-code)    │
+ *   │       ▼              │                │       ▼                  │
+ *   │  SdkControlServer    │   stdin/stdout │  SdkControlClient        │
+ *   │  Transport           │◄──────────────►│  Transport               │
+ *   └──────────────────────┘   控制协议      └──────────────────────────┘
+ *
+ * CLI 侧把 MCP JSON-RPC 包装为 control_request(subtype: mcp_message)，
+ * SDK 宿主解包转发给 MCP Server，响应通过 control_response 回传。
+ *
+ * 对齐 Claude Code SdkControlTransport（spec §5.3）。
+ */
+
+/** MCP JSON-RPC 消息（简化版，对齐 @modelcontextprotocol/sdk） */
+export interface JSONRPCMessage {
+  jsonrpc: "2.0";
+  id?: string | number;
+  method?: string;
+  params?: unknown;
+  result?: unknown;
+  error?: { code: number; message: string };
+}
+
+/** MCP Transport 接口（简化版） */
+export interface MCPTransport {
+  send(message: JSONRPCMessage): Promise<void>;
+  onmessage?: (message: JSONRPCMessage) => void;
+  start(): Promise<void>;
+  close(): Promise<void>;
+}
+
+/**
+ * CLI 侧 Transport：将 MCP 消息包装为控制协议消息发往 SDK 宿主
+ */
+export class SdkControlClientTransport implements MCPTransport {
+  private serverName: string;
+  private sendMcpMessage: (
+    serverName: string,
+    message: JSONRPCMessage,
+  ) => Promise<JSONRPCMessage>;
+
+  onmessage?: (message: JSONRPCMessage) => void;
+
+  constructor(
+    serverName: string,
+    sendMcpMessage: (name: string, msg: JSONRPCMessage) => Promise<JSONRPCMessage>,
+  ) {
+    this.serverName = serverName;
+    this.sendMcpMessage = sendMcpMessage;
+  }
+
+  async send(message: JSONRPCMessage): Promise<void> {
+    const response = await this.sendMcpMessage(this.serverName, message);
+    this.onmessage?.(response);
+  }
+
+  async start(): Promise<void> {}
+  async close(): Promise<void> {}
+}
+
+/**
+ * SDK 宿主侧 Transport：接收控制协议消息，转发给 MCP Server
+ */
+export class SdkControlServerTransport implements MCPTransport {
+  private sendResponse: (message: JSONRPCMessage) => void;
+  onmessage?: (message: JSONRPCMessage) => void;
+
+  constructor(sendResponse: (message: JSONRPCMessage) => void) {
+    this.sendResponse = sendResponse;
+  }
+
+  async send(message: JSONRPCMessage): Promise<void> {
+    this.sendResponse(message);
+  }
+
+  /** 从控制协议接收消息，转发给 MCP Server */
+  receiveFromControl(message: JSONRPCMessage): void {
+    this.onmessage?.(message);
+  }
+
+  async start(): Promise<void> {}
+  async close(): Promise<void> {}
+}
+
+/**
+ * 同进程 MCP Transport 对（用于内置 SDK 工具）
+ * 通过 queueMicrotask 异步投递，避免同步调用栈溢出
+ */
+export function createLinkedTransportPair(): [MCPTransport, MCPTransport] {
+  class InProcessTransport implements MCPTransport {
+    private peer?: InProcessTransport;
+    onmessage?: (message: JSONRPCMessage) => void;
+
+    setPeer(peer: InProcessTransport): void {
+      this.peer = peer;
+    }
+
+    async send(message: JSONRPCMessage): Promise<void> {
+      const peer = this.peer;
+      queueMicrotask(() => {
+        peer?.onmessage?.(message);
+      });
+    }
+
+    async start(): Promise<void> {}
+    async close(): Promise<void> {}
+  }
+
+  const a = new InProcessTransport();
+  const b = new InProcessTransport();
+  a.setPeer(b);
+  b.setPeer(a);
+  return [a, b];
+}
diff --git a/src/sdk/message-converter.ts b/src/sdk/message-converter.ts
new file mode 100644
index 0000000..00305cd
--- /dev/null
+++ b/src/sdk/message-converter.ts
@@ -0,0 +1,161 @@
+/**
+ * 消息转换器：QueryEngineEvent → SDKMessage
+ *
+ * 将内部事件流转换为标准化 SDK 消息协议。
+ * 返回 null 表示该事件不转发给 SDK 调用者（内部控制信号）。
+ *
+ * 映射关系见 spec §3.6 / §4.4。done 与 max_turns 的 result 消息中
+ * 部分字段（result 文本 / duration_api_ms）由 SDKQueryEngine 在合成时补齐，
+ * 这里给出结构骨架。
+ */
+
+import type { QueryEngineEvent } from "../query/types.ts";
+import type { SDKMessage } from "./types.ts";
+import type { Usage } from "../llm/types.ts";
+
+export interface ConvertContext {
+  sessionId: string;
+  totalUsage: Usage;
+  startTime: number;
+  turnCount: number;
+  totalCostUsd: number;
+  /** 单调时钟（可注入，便于测试）；默认 Date.now */
+  now?: () => number;
+  /** UUID 生成（可注入，便于测试）；默认 crypto.randomUUID */
+  uuid?: () => string;
+}
+
+function nowOf(ctx: ConvertContext): number {
+  return (ctx.now ?? Date.now)();
+}
+
+function uuidOf(ctx: ConvertContext): string {
+  return (ctx.uuid ?? (() => crypto.randomUUID()))();
+}
+
+/**
+ * 将 QueryEngineEvent 转换为 SDKMessage
+ * @returns SDKMessage 或 null（不转发）
+ */
+export function convertToSDKMessage(
+  event: QueryEngineEvent,
+  ctx: ConvertContext,
+): SDKMessage | null {
+  switch (event.kind) {
+    case "user_message_added":
+      // 用户消息由 SDKQueryEngine 在添加时直接 yield，这里不重复
+      return null;
+
+    case "assistant_message":
+      return {
+        type: "assistant",
+        uuid: uuidOf(ctx),
+        session_id: ctx.sessionId,
+        message: event.message,
+        stop_reason: null,
+        usage: { ...ctx.totalUsage },
+      };
+
+    case "stream_text":
+      return {
+        type: "stream_event",
+        event: { type: "content_block_delta", text: event.text },
+      };
+
+    case "tool_start":
+      return {
+        type: "tool_progress",
+        tool_name: event.toolName,
+        status: "start",
+        input: event.toolInput,
+      };
+
+    case "tool_end":
+      return {
+        type: "tool_progress",
+        tool_name: event.toolName,
+        status: "end",
+        result: event.result
+          ? {
+              is_error: event.result.isError,
+              elapsed_ms: event.result.elapsedMs,
+            }
+          : undefined,
+      };
+
+    case "compact":
+      return {
+        type: "system",
+        subtype: "compact_boundary",
+      };
+
+    case "context_warning":
+      return {
+        type: "system",
+        subtype: "status",
+        message: `上下文剩余 ${event.remaining}%`,
+      };
+
+    case "max_turns":
+      return {
+        type: "result",
+        subtype: "error_max_turns",
+        errors: [`达到最大轮次限制: ${event.maxTurns}`],
+        duration_ms: nowOf(ctx) - ctx.startTime,
+        num_turns: ctx.turnCount,
+        total_cost_usd: ctx.totalCostUsd,
+        usage: { ...ctx.totalUsage },
+        session_id: ctx.sessionId,
+      };
+
+    case "done":
+      return {
+        type: "result",
+        subtype: "success",
+        duration_ms: nowOf(ctx) - ctx.startTime,
+        duration_api_ms: 0, // 由 SDKQueryEngine 用 SessionState 补齐
+        is_error: false,
+        num_turns: event.turns,
+        result: "", // 由 SDKQueryEngine 填充最终文本
+        stop_reason: "end_turn",
+        total_cost_usd: ctx.totalCostUsd,
+        usage: { ...ctx.totalUsage },
+        session_id: ctx.sessionId,
+      };
+
+    case "hook_blocked":
+      return {
+        type: "system",
+        subtype: "hook_response",
+        hook_event: "user_prompt_submit",
+        decision: event.reason,
+      };
+
+    case "loop_detected":
+      return {
+        type: "system",
+        subtype: "status",
+        message: `循环检测: ${event.detail}`,
+      };
+
+    case "loop_recovery":
+      return {
+        type: "system",
+        subtype: "status",
+        message: `循环恢复尝试 ${event.attempt}/${event.maxAttempts}`,
+      };
+
+    case "system":
+      return {
+        type: "system",
+        subtype: "status",
+        message: event.text,
+      };
+
+    case "tombstone":
+      return null; // 内部控制信号，不转发
+
+    default:
+      return null;
+  }
+}
diff --git a/src/sdk/ndjson.ts b/src/sdk/ndjson.ts
new file mode 100644
index 0000000..e102444
--- /dev/null
+++ b/src/sdk/ndjson.ts
@@ -0,0 +1,60 @@
+/**
+ * NDJSON 安全序列化/反序列化
+ *
+ * NDJSON（Newline-Delimited JSON）用换行符分隔每条 JSON 消息。
+ * 关键陷阱：U+2028（行分隔符）和 U+2029（段落分隔符）在 JSON 中合法，
+ * 但部分解析器/管道会把它们当作换行，破坏 NDJSON 的行分隔假设。
+ * 序列化时必须转义。
+ *
+ * 实现注意：用 String.fromCharCode 构造匹配字符，避免源码里出现裸 U+2028/U+2029
+ * （它们本身是 JS 行终止符，会破坏源码解析）。
+ */
+
+const LS = String.fromCharCode(0x2028); // U+2028 行分隔符
+const PS = String.fromCharCode(0x2029); // U+2029 段落分隔符
+const LS_RE = new RegExp(LS, "g");
+const PS_RE = new RegExp(PS, "g");
+
+/**
+ * NDJSON 安全序列化
+ * 转义 U+2028/U+2029，防止行分隔符误切割 JSON
+ */
+export function ndjsonStringify(obj: unknown): string {
+  return JSON.stringify(obj)
+    .replace(LS_RE, "\\u2028")
+    .replace(PS_RE, "\\u2029");
+}
+
+/**
+ * NDJSON 安全反序列化
+ * 逐行解析，空行返回 null
+ */
+export function ndjsonParse(line: string): unknown {
+  const trimmed = line.trim();
+  if (!trimmed) return null;
+  return JSON.parse(trimmed);
+}
+
+/**
+ * 从 ReadableStream 创建 NDJSON 行迭代器
+ *
+ * 处理跨 chunk 的不完整行：缓冲未遇到换行的尾部，下一个 chunk 拼接。
+ * 兼容 Node.js Readable（Buffer/string chunk）。
+ */
+export async function* ndjsonLines(
+  input: NodeJS.ReadableStream,
+): AsyncGenerator<string> {
+  let buffer = "";
+  for await (const chunk of input) {
+    buffer += typeof chunk === "string" ? chunk : chunk.toString("utf-8");
+    const lines = buffer.split("\n");
+    // 最后一段可能是不完整行，留到下一个 chunk
+    buffer = lines.pop() ?? "";
+    for (const line of lines) {
+      const trimmed = line.trim();
+      if (trimmed) yield trimmed;
+    }
+  }
+  // 处理最后一行（无换行符结尾）
+  if (buffer.trim()) yield buffer.trim();
+}
diff --git a/src/sdk/permission-bridge.ts b/src/sdk/permission-bridge.ts
new file mode 100644
index 0000000..91329d9
--- /dev/null
+++ b/src/sdk/permission-bridge.ts
@@ -0,0 +1,109 @@
+/**
+ * SDK 模式权限桥接（控制协议 ↔ 权限检查）
+ *
+ * SDK 模式下没有 TUI 弹窗，权限决策来自两个并行来源，先决定者胜出：
+ * 1. Hook（PreToolUse）—— 本地静态规则 / 脚本
+ * 2. SDK 宿主 —— 通过控制协议 can_use_tool 请求询问外部调用者
+ *
+ * Promise.race：谁先决定用谁的结果。Hook 先决定 → 取消 SDK 请求；
+ * SDK 先响应 → 取消 Hook（abort signal）。
+ *
+ * 对齐 Claude Code StructuredIO.createCanUseTool() 的竞速设计（spec §5.2）。
+ * 注意：sid-code 的 HookDecision 为 "allow" | "deny" | "block"，
+ * 没有 shouldAutoApprove()，这里用 decision === "allow" 表示 Hook 主动放行。
+ */
+
+import type { StructuredIO } from "./structured-io.ts";
+import type { SDKControlPermissionResponse } from "./types.ts";
+import { SDKControlPermissionResponseSchema } from "./control-schemas.ts";
+import type { HookSystem } from "../hook/system.ts";
+
+export type PermissionBehavior = "allow" | "deny" | "always_allow";
+
+export interface PermissionBridgeOptions {
+  structuredIO: StructuredIO;
+  hookSystem?: HookSystem;
+}
+
+/**
+ * 创建 SDK 模式下的权限检查函数
+ *
+ * 返回的函数签名与内核权限检查器对齐：(toolName, toolInput, toolUseId) → behavior
+ */
+export function createSDKCanUseTool(opts: PermissionBridgeOptions) {
+  const { structuredIO, hookSystem } = opts;
+
+  return async (
+    toolName: string,
+    toolInput: unknown,
+    toolUseId: string,
+  ): Promise<PermissionBehavior> => {
+    const hookAbortController = new AbortController();
+
+    // Hook 评估（无 Hook 时永不 resolve，交给 SDK 宿主决定）
+    const hookPromise: Promise<PermissionBehavior | null> = hookSystem
+      ? executePermissionHook(hookSystem, toolName, toolInput, hookAbortController.signal)
+      : new Promise<PermissionBehavior | null>(() => {});
+
+    // SDK 宿主权限请求
+    const sdkPromise = structuredIO.sendRequest<SDKControlPermissionResponse>(
+      {
+        subtype: "can_use_tool",
+        tool_name: toolName,
+        input: (toolInput ?? {}) as Record<string, unknown>,
+        tool_use_id: toolUseId,
+      },
+      SDKControlPermissionResponseSchema(),
+      hookAbortController.signal,
+    );
+
+    // 竞速
+    const winner = await Promise.race([
+      hookPromise.then((r) => ({ source: "hook" as const, result: r })),
+      sdkPromise.then((r) => ({ source: "sdk" as const, result: r })),
+    ]);
+
+    if (winner.source === "hook" && winner.result) {
+      // Hook 先决定 → 取消 SDK 请求
+      hookAbortController.abort();
+      return winner.result;
+    }
+
+    if (winner.source === "sdk") {
+      // SDK 宿主先响应
+      structuredIO.trackResolvedToolUseId(toolUseId);
+      return winner.result.behavior;
+    }
+
+    // Hook 放弃决定（resolve null）→ 等待 SDK 宿主
+    const sdkResult = await sdkPromise;
+    structuredIO.trackResolvedToolUseId(toolUseId);
+    return sdkResult.behavior;
+  };
+}
+
+/**
+ * 执行 PreToolUse Hook，映射为权限 behavior
+ * @returns "deny"（阻塞）/ "allow"（主动放行）/ null（不做决定）
+ */
+async function executePermissionHook(
+  hookSystem: HookSystem,
+  toolName: string,
+  toolInput: unknown,
+  signal: AbortSignal,
+): Promise<PermissionBehavior | null> {
+  try {
+    const result = await hookSystem.firePreToolUseEvent(
+      toolName,
+      (toolInput ?? {}) as Record<string, unknown>,
+    );
+    if (signal.aborted) return null;
+    const out = result.finalOutput;
+    if (!out) return null;
+    if (out.isBlockingDecision()) return "deny";
+    if (out.decision === "allow") return "allow";
+    return null; // Hook 未做决定，交给 SDK 宿主
+  } catch {
+    return null;
+  }
+}
