+    snap.items[0].challengesAcknowledged = 99;
+    const b = new HypothesisLedger();
+    b.hydrate(snap);
+    expect(b.get(h.id)!.challengesAcknowledged).toBe(1);
+    expect(b.hasChallengedConfirmed()).toBe(false);
+  });
+});
