+    const r = ledger.challenge({ id: h.id, verdict: "confirm", evidence: ev, turn: 6 });
+    expect(r.redundant).toBe(false);
+    expect(ledger.hasChallengedConfirmed()).toBe(false);
+  });
+});
+
+describe("机制总开关：SID_DISABLE_HYPOTHESIS", () => {
+  test("默认开启；设为 1 时关闭", () => {
+    const saved = process.env.SID_DISABLE_HYPOTHESIS;
+    try {
+      delete process.env.SID_DISABLE_HYPOTHESIS;
+      expect(isHypothesisEnabled()).toBe(true);
+      process.env.SID_DISABLE_HYPOTHESIS = "1";
+      expect(isHypothesisEnabled()).toBe(false);
+      // 只认 "1"，避免 SID_DISABLE_HYPOTHESIS=0 被误读成关闭
+      process.env.SID_DISABLE_HYPOTHESIS = "0";
+      expect(isHypothesisEnabled()).toBe(true);
+    } finally {
+      if (saved === undefined) delete process.env.SID_DISABLE_HYPOTHESIS;
+      else process.env.SID_DISABLE_HYPOTHESIS = saved;
+    }
+  });
