+  });
+  test("无引号内换行 → 放行", () => {
+    expect(validateQuotedNewline("echo hello # comment")).toBeNull();
+  });
+});
+
+describe("validateProcessSubstitution", () => {
+  test("进程替换 <() >() → 命中", () => {
