+    expect(validateProcessSubstitution("ls -la")).toBeNull();
+    expect(validateProcessSubstitution("cat file.txt")).toBeNull();
+  });
+});
+
+describe("validateZshDangerousCommands", () => {
+  test("zmodload / sysopen / ztcp → 命中", () => {
