+    // （这里特意把三层超时都设为 60s）才退出，从而暴露回归。
+    const ctl = new AbortController();
+    let neverSettles: () => void = () => {};
+    async function* trulyHanging(): AsyncIterable<Evt> {
+      yield { type: "content_block_delta" };
