+  const drop = dropped ? c("gray", `  弃用 ${dropped}(有 fetch 未走到 completed)`) : "";
+  const legacy = opts?.noDimension
+    ? c("gray", `  另 ${opts.noDimension} 个样本来自埋点上线前的轨迹`)
+    : "";
+  return `TTFT 命中:${fmt(hit)} 未命中:${fmt(miss)}${delta}${drop}${legacy}`;
+}

