+function entry(over: Partial<UsageLedgerEntry> = {}): UsageLedgerEntry {
+  return {
+    ts: 1786000000,
+    sessionId: `s-${Math.round(over.ts ?? 1786000000)}-${over.model ?? "m"}`,
+    model: "glm-5.2",
+    promptTotal: 10000,
