+    expect(body).toContain("--merge");
+    // 必须给出可核验的判据，而不是只写一句"要用 merge"
+    expect(body).toContain("merge-base --is-ancestor");
+  });
+
+  test("release.sh 收尾指引提到保护与 PR 路径（不让人先撞一次 GH013）", () => {
+    const seg = RELEASE_SH.slice(posOf("官网 /changelog 是站点构建期快照"));
